comms.text:
@1 דַיָנִין וּפֻרְעָנִין תְּמַנֵי לָךְ בְּכֹל קִרְוָיךְ דִי יְיָ אֱלָהָךְ יָהֵב לָךְ לְשִׁבְטָיךְ וִידוּנוּן יָת עַמָא דִין דִקְשׁוֹט:
@2 לָא תַצְלֵי דִין לָא תִשְׁתְּמוֹדַע אַפִּין וְלָא תְקַבֵּל שֹׁחֲדָא אֲרֵי שֹׁחֲדָא מְעַוֵּר עֵינֵי חַכִּימִין וּמְקַלְקַל פִּתְגָמִין תְּרִיצִין:
@3 קֻשְׁטָא קֻשְׁטָא תְּהֵי רָדִיף בְּדִיל דְתֵיחֵי וְתֵירַת יָת אַרְעָא דַיְיָ אֱלָהָךְ יָהֵב לָךְ:
@4 לָא תִצוֹב לָךְ אֲשֵׁרַת כָּל אִילָן בִּסְטַר מַדְבְּחָא דַיְיָ אֱלָהָךְ דִי תַעְבֶּד לָךְ:
@5 וְלָא תְקִים לָךְ קָמָא דִי סָנֵי יְיָ אֱלָהָךְ:
@6 לָא תִכּוֹס קֳדָם יְיָ אֱלָהָךְ תּוֹר וְאִמָר דִי יְהֵי בֵהּ מוּמָא כֹּל מִדַעַם בִּישׁ אֲרֵי מְרָחָק קֳדָם יְיָ אֱלָהָךְ הוּא:
@7 אֲרֵי יִשְׁתְּכַח בֵּינָךְ בַּחֲדָא מִקִרְוָיךְ דַיְיָ אֱלָהָךְ יָהֵב לָךְ גְבַר אוֹ אִתְּתָא דִי יַעְבֵּד יָת דְבִישׁ קֳדָם יְיָ אֱלָהָךְ לְמֶעְבַּר עַל קְיָמֵהּ:
@8 וַאֲזַל וּפְלַח לְטַעֲוַת עַמְמַיָא וּסְגִיד לְהוֹן וּלְשִׁמְשָׁא אוֹ לְסִיהֲרָא אוֹ לְכָל חֵילֵי שְׁמַיָא דִי לָא פַקֵדִית:
@9 וְיִתְחַוֵי לָךְ וְתִשְׁמַע וְתִתְבַּע יָאוּת וְהָא קֻשְׁטָא כֵּוַן פִּתְגָמָא אִתְעֲבִידַת תּוֹעֶבְתָּא הָדָא בְּיִשְׂרָאֵל:
@10 וְתַפֵּק יָת גַבְרָא הַהוּא אוֹ יָת אִתְּתָא הַהִיא דִי עֲבָדוּ יָת פִּתְגָמָא בִישָׁא הָדֵין לִתְרַע בֵּית דִינָךְ יָת גַבְרָא אוֹ יָת אִתְּתָא וְתִרְגְמִנוּן בְּאַבְנַיָא וִימוּתוּן:
@11 עַל מֵימַר תְּרֵין סַהֲדִין אוֹ תְּלָתָא סַהֲדִין יִתְקְטִל דְחַיַב קְטוֹל לָא יִתְקְטֵל עַל מֵימַר סָהִיד חָד:
@12 יְדָא דְסַהֲדַיָא תְּהֵי בֵהּ בְּקַדְמֵיתָא לְמִקְטְלֵהּ וִידָא דְכָל עַמָא בְּבַתְרֵיתָא וּתְפַלֵי עָבֵד דְבִישׁ מִבֵּינָךְ:
@13 אֲרֵי יִתְכַסֵי מִנָךְ פִּתְגָמָא לְדִינָא בֵּין דְמָא לִדְמָא בֵּין דִינָא לְדִינָא וּבֵין מַכְתַּשׁ סְגִירוּ לְמַכְתַּשׁ סְגִירוּ פִּתְגָמֵי פְלֻגְתָּא דִינָא בְּקִרְוָיךְ וּתְקוּם וְתִסַק לְאַתְרָא דִי יִתִּרְעֵי יְיָ אֱלָהָךְ בֵּהּ:
@14 וְתֵיתֵי לְוָת כָּהֲנַיָא לֵוָאֵי וּלְוָת דַיָנָא דִי יְהֵי בְּיוֹמַיָא הָאִנוּן וְתִתְבַּע וִיחַוּוּן לָךְ יָת פִּתְגָמָא דְדִינָא:
@15 וְתַעְבֵּד עַל מֵימַר פִּתְגָמָא דִי יְחַוּוּן לָךְ מִן אַתְרָא הַהוּא דִי יִתִּרְעֵי יְיָ וְתִטַר לְמֶעְבַּד כְּכֹל דִי יַלְפֻנָךְ:
@16 עַל מֵימַר אוֹרַיְתָא דִי יַלְפֻנָךְ וְעַל דִינָא דִי יֵימְרוּן לָךְ תַּעְבֵּד לָא תִסְטֵּי מִן פִּתְגָמָא דִי יְחַוּוּן לָךְ יַמִינָא וּשְׂמָאלָא:
@17 וּגְבַר דִי יַעְבֵּד בִּרְשַׁע בְּדִיל דְלָא לְקַבָּלָא מִן כַּהֲנָא דְקָאֵם לְשַׁמָשָׁא תַמָן קֳדָם יְיָ אֱלָהָךְ אוֹ מִן דַיָנָא וְיִתְקְטֵל גַבְרָא הַהוּא וּתְפַלֵי עָבֵד דְבִישׁ מִיִשְׂרָאֵל:
@18 וְכָל עַמָא יִשְׁמְעוּן וְיִדְחֲלוּן וְלָא יַרְשִׁיעוּן עוֹד:
@19 אֲרֵי תֵעוֹל לְאַרְעָא דַיְיָ אֱלָהָךְ יָהֵב לָךְ וְתֵירְתַהּ וְתֵיתֵב בַּהּ וְתֵימַר אֱמַנִי עֲלַי מַלְכָּא כְּכָל עַמְמַיָא דִי בְסַחֲרָנָי:
@20 מַנָאָה תְמַנֵי עֲלָךְ מַלְכָּא דִי יִתִּרְעֵי יְיָ אֱלָהָךְ בֵּהּ מִגוֹ אַחָיךְ תְּמַנֵי עֲלָךְ מַלְכָּא לֵת לָךְ רְשׁוּ לְמַנָאָה עֲלָךְ גְבַר נוּכְרַי דִי לָא אֲחוּךְ הוּא:
@21 לְחוֹד לָא יַסְגֵי לֵהּ סוּסָוָן וְלָא יָתֵב יָת עַמָא לְמִצְרָיִם בְּדִיל לְאַסְגָּאָה לֵהּ סוּסָוָן וַיְיָ אֲמַר לְכוֹן לָא תוֹסְפוּן לְמִתוּב בְּאֹרַח הָדֵין עוֹד:
@22 וְלָא יַסְגֵי לֵהּ נְשִׁין וְלָא יִטְעֵי לִבֵּהּ וְכַסְפָּא וְדַהַבָא לָא יַסגֵי לֵהּ לַחֲדָא:
@23 וִיהֵי:כְמִתְּבֵהּ עַל כָּרְסָא מַלְכוּתֵהּ וְיִכְתּוֹב לֵהּ יָת פַּתְשֶׁגֶן אוֹרַיְתָא הָדָא עַל סִפְרָא מִן קֳדָם כָּהֲנַיָא לֵוָאֵי:
@24 וּתְהֵי עִמֵהּ וִיהֵי קָרֵי בֵהּ כָּל יוֹמֵי חַיוֹהִי בְּדִיל דְיֵלַף לְמִדְחַל קֳדָם יְיָ אֱלָהֵהּ לְמִטַּר יָת כָּל פִּתְגָמֵי אוֹרַיְתָא הָדָא וְיָת קְיָמַיָא הָאִלֵין לְמֶעְבָּדְהוֹן:
@25 בְּדִיל דְלָא יְרִים לִבֵּהּ מֵאֲחוֹהִי וּבְדִיל דְלָא יִסְטֵּי מִן תַּפְקֶדְתָּא יַמִינָא וּשְׂמָאלָא בְּדִיל דְיוֹרֵךְ יוֹמִין עַל מַלְכוּתֵהּ הוּא וּבְנוֹהִי בְּגוֹ יִשְׂרָאֵל:
@26 לָא יְהֵי לְכָהֲנַיָא לֵוָאֵי כָּל שִׁבְטָא דְלֵוִי חֳלָק וְאַחֲסָנָא עִם יִשְׂרָאֵל קֻרְבָּנַיָא דַיְיָ וְאַחֲסַנְתֵּהּ יֵיכְלוּן:
@27 וְאַחֲסָנָא לָא יְהֵי לֵהּ בְּגוֹ אֲחוֹהִי מַתְּנָן דִיהַב לֵהּ יְיָ אִנוּן אַחֲסַנְתֵּהּ כְּמָא דִי מַלִיל לֵהּ:
@28 וְדֵין יְהֵי דְחָזֵי לְכָהֲנַיָא מִן עַמָא מִן נָכְסֵי נִכְסָתָא אִם תּוֹר אִם אִמָר וְיִתֵּן לְכַהֲנָא דְרוֹעָא וְלוֹעָא וְקֻבְתָא:
@29 רֵישׁ עִבוּרָךְ חַמְרָךְ וּמִשְׁחָךְ וְרֵישׁ גִזָא דְעָנָךְ תַּפְרֵשׁ לֵהּ:
@30 אֲרֵי בֵהּ יִתִּרְעֵי יְיָ אֱלָהָךְ מִכָּל שִׁבְטָיךְ לְמֵקַם לְשַׁמָשָׁא בִשְׁמָא דַיְיָ הוּא וּבְנוֹהִי כָּל יוֹמַיָא:
@31 וַאֲרֵי יֵיתֵי לֵוָאָה מֵחֲדָא מִקִרְוָיךְ מִכָּל יִשְׂרָאֵל דִי הוּא דָר תַּמָן וְיֵיתֵי בְּכָל רְעוּת נַפְשֵׁהּ לְאַתְרָא דִי יִתִּרְעֵי יְיָ:
@32 וִישַׁמַשׁ בִּשְׁמָא דַיְיָ אֱלָהֵהּ כְּכָל אֲחוֹהִי לֵוָאֵי דִמְשַׁמְשִׁין תַּמָן (בִּצְלוֹ) קֳדָם יְיָ:
@33 חֳלָק כָּחֳלָק יֵיכְלוּן בַּר מִמַטַרְתָּא דְיֵיתֵי בְּשַׁבַּתָּא דְכֵן אַתְקִינוּ אֲבָהָתָא:
@34 אֲרֵי אַתְּ עָלֵל לְאַרְעָא דַיְיָ אֱלָהָךְ יָהֵב לָךְ לָא תֵילַף לְמֶעְבַּד כְּתֹעֲבַת עַמְמַיָא הָאִנוּן:
@35 לָא יִשְׁתְּכַח בָּךְ מַעֲבַר בְּרֵהּ וּבְרַתֵּהּ בְּנוּרָא קָסֵם קֻסְמִין מְעָנֵן וּמְנַחֵשׁ וְחָרָשׁ:
@36 וְרָטִין רְטָן וְשָׁאֵל בִּדִין וּדְכוּרוּ וְתָבַע מִן מֵתַיָא:
@37 אֲרֵי מְרָחָק יְיָ כָּל דְיַעְבֵּד אִלֵין וּבְדִיל תּוֹעֲבָתָא הָאִלֵין יְיָ אֱלָהָךְ מְתָרַךְ יָתְהוֹן מִקֳדָמָךְ:
@38 שְׁלִים תְּהֵי בְּדַחַלְתָּא דַיְיָ אֱלָהָךְ:
@39 אֲרֵי עַמְמַיָא הָאִלֵין דִי אַתְּ יָרֵת יָתְהוֹן מִן מְעָנְנַיָא וּמִן קַסָמַיָא שָׁמְעִין וְאַתְּ לָא כֵן יְהַב לָךְ יְיָ אֱלָהָךְ:
@40 נְבִיָא מִבֵּינָךְ מֵאַחָיךְ כְּוָתִי יְקִים לָךְ יְיָ אֱלָהָךְ מִנֵהּ תְּקַבְּלוּן:
@41 כְּכֹל דִי שְׁאֶלְתָּא מִקֳדָם יְיָ אֱלָהָךְ בְּחֹרֵב בְּיוֹמָא דִקְהָלָא לְמֵימָר לָא אוֹסֵף לְמִשְׁמָע יָת קָל מֵימְרָא דַיְיָ אֱלָהַי וְיָת אֶשָׁתָא רַבְּתָא הָדָא לָא אֶחֱזֵי עוֹד וְלָא אֵמוּת:
@42 וַאֲמַר יְיָ לִי אוֹטִיבוּ דִי מַלִילוּ:
@43 נְבִיָא אֲקִים לְהוֹן מִגוֹ אֲחֵיהוֹן כְּוָתָךְ וְאֶתֵּן פִּתְגָמֵי נְבוּאָתִי בְּפוּמֵהּ וִימַלֵל עִמְהוֹן יָת כָּל דִי אֲפַקְדִנֵהּ:
@44 וִיהֵי גַבְרָא דִי לָא יְקַבֵּל לְפִתְגָמַי דִי יְמַלֵל בִּשְׁמִי מֵימְרִי יִתְבַּע מִנֵהּ:
@45 בְּרַם נְבִיָא דִי יַרְשַׁע לְמַלָלָא פִתְגָמָא בִּשְׁמִי יָת דִי לָא פַקֵדִתֵּה לְמַלָלָא וְדִי יְמַלֵיל בְּשׁוּם טַעֲוַת עַמְמַיָא וְיִתְקְטֵל נְבִיָא הַהוּא:
@46 וַאֲרֵי תֵימַר בְּלִבָּךְ אֶכְדֵן נִדַע יָת פִּתְגָמָא דִי לָא מַלְלֵהּ יְיָ:
@47 דִי יְמַלֵל נְבִיָא בִּשְׁמָא דַיְיָ וְלָא יְהֵי פִתְגָמָא וְלָא יִתְקַיַם הוּא פִתְגָמָא דִי לָא מַלְלֵהּ יְיָ בִּרְשַׁע מַלְלֵהּ נְבִיָא לָא תִדְחַלּ מִנֵהּ:
@48 אֲרֵי יְשֵׁצֵי יְיָ אֱלָהָךְ יָת עַמְמַיָא דִי יְיָ אֱלָהָךְ יָהֵב לָךְ יָת אַרְעֲהוֹן וְתֵרְתִנוּן וְתֵיתֵב בְּקִרְוֵיהוֹן וּבְבָתֵּיהוֹן:
@49 תְּלַת קִרְוִין תַּפְרֵשׁ לָךְ בְּגוֹ אַרְעָךְ דִי יְיָ אֱלָהָךְ יָהֵב לָךְ לְמֵירְתַהּ:
@50 תְּתַקֵן לָךְ אָרְחָא וּתְתַלַת יָת תְּחוּם אַרְעָךְ דִי יַחְסְנִנָךְ יְיָ אֱלָהָךְ וִיהֵי לְמֵעִירוֹק תַּמָן כָּל קָטוֹלָא:
@51 וְדֵין פִּתְגַם קָטוֹלָא דְיֵעִרוֹק תַּמָן וְיִתְקַיַם דִי יִקְטוֹל יָת חַבְרֵהּ בְּלָא מַנְדְעֵהּ וְהוּא לָא סָנֵי לֵהּ מֵאִתְמַלֵי וּמִדְקָמוֹהִי:
@52 וְדִי יֵעוֹל עִם חַבְרֵהּ בְּחֻרְשָׁא לְמִקַץ אָעִין וְתִתְמְרֵיג יְדֵהּ בְּפַרְזְלָא לְמִקַץ אָעָא וְיִשְׁתְּלֵף פַּרְזְלָא מִן אָעָא וְיַשְׁכַּח יָת חַבְרֵהּ וִימוּת הוּא יֵעִרוֹק לַחֲדָא מִן קִרְוַיָא הָאִלֵין וְיִתְקַיַם:
@53 דִילְמָא יִרְדוֹף גָאֵל דְמָא בָּתַר קָטוֹלָא אֲרֵי יֵחַם לִבֵּה וְיַדְבְּקִנֵהּ אֲרֵי תִסְגֵי אָרְחָא וְיִקְטְלִנֵהּ נְפַשׁ וְלֵהּ לֵית חוֹבַת דִין דִקְטוֹל אֲרֵי לָא סָנֵי הוּא לֵהּ מִתְּמַלֵי וּמִדְקָמוֹהִי:
@54 עַל כֵּן אֲנָא מְפַקְדָךְ לְמֵימָר תְּלַת קִרְוִין תַּפְרֵשׁ לָךְ:
@55 וְאִם יַפְתֵּי יְיָ אֱלָהָךְ יָת תְּחוּמָךְ כְּמָא דִי קַיִים לַאֲבָהָתָךְ וְיִתֶּן לָךְ יָת כָּל אַרְעָא דִי מַלִיל לְמִתַּן לַאֲבָהָתָךְ:
@56 אֲרֵי תִטַר יָת כָּל תַּפְקֶדְתָּא הָדָא לְמֶעְבְּדַהּ דִי אֲנָא מְפַקְדָךְ יוֹמָא דֵין לְמִרְחַם יָת יְיָ אֱלָהָךְ וְלִמְהַךְ בְּאָרְחָן דְתַקְנָן קֳדָמוֹהִי כָּל יוֹמַיָא וְתוֹסֵף לָךְ עוֹד תְּלַת קִרְוִין עַל תְּלַת אִלֵין:
@57 וְלָא יִשְׁתְּפֵךְ דָם זַכַּי בְּגוֹ אַרְעָךְ דִי יְיָ אֱלָהָךְ יָהֵב לָךְ אַחֲסָנָא וִיהֵי עֲלָךְ חוֹבַת דִין דִקְטוֹל:
@58 וַאֲרֵי יְהֵי גְבַר סָנֵי לְחַבְרֵהּ וְיִכְמַן לֵהּ וִיקוּם עֲלוֹהִי וְיִמְחִנֵהּ נְפָשׁ וִימוּת וְיֵעִרוֹק לַחֲדָא מִן קִרְוַיָא הָאִלֵין:
@59 וִישַׁלְחוּן סָבֵי קַרְתֵּהּ וְיִדְבְּרוּן יָתֵהּ מִתַּמָן וְיִתְּנוּן יָתֵהּ בְּיַד גָאֵל דְמָא וִימוּת:
@60 לָא תְחוּס עֵינָךְ עֲלוֹהִי וּתְפַלֵי אַשְׁדִי דָם זַכַּי מִיִשְׂרָאֵל וְיֵיטַב לָךְ:
@61 לָא תַשְׁנֵי תְּחוּמָא דְחַבְרָךְ דִי תְחִימוּ קַדְמָאֵי בְּאַחֲסַנְתָּךְ דִי תַחֲסֵן בְּאַרְעָא דִי יְיָ אֱלָהָךְ יָהֵב לָךְ לְמֵירְתַהּ:
@62 לָא יְקוּם סָהִיד חַד בִּגְבַר לְכָל עַוָיָן וּלְכָל חוֹבִין בְּכָל חֵט דִי יֶחְטֵי עַל מֵימַר תְּרֵין סָהֲדִין אוֹ עַל מֵימַר תְּלָתָא סָהֲדִין יִתְקַיַם פִּתְגָמָא:
@63 אֲרֵי יְקוּם סָהִיד שְׁקַר בִּגְבָר לְאַסְהָדָא בֵהּ סַטְּיָא:
@64 וִיקוּמוּן תְרֵין גֻבְרִין דִי לְהוֹן דִינָא קֳדָם יְיָ קֳדָם כָּהֲנַיָא וְדַיָנַיָא דִי יְהוֹן בְּיוֹמַיָא הָאִנוּן:
@65 וְיִתְבְּעוּן דַיָנַיָא יָאוּת וְהָא סָהִיד שְׁקַר סָהֲדָא שִׁקְרָא אַסְהַד בַּאֲחוֹהִי:
@66 וְתַעְבְּדוּן לֵהּ כְּמָא דִי חַשִׁיב לְמֶעְבַּד לַאֲחוֹהִי וּתְפַלֵי עָבֵד דְבִישׁ מִבֵּינָךְ:
@67 וּדְיִשְׁתַּאֲרוּן יִשְׁמְעוּן וְיִדְחֲלוּן וְלָא יוֹסְפוּן לְמֶעְבַּד עוֹד כְּפִתְגָמָא בִישָׁא הָדֵין בֵּינָךְ:
@68 וְלָא תְחוּס עֵינָךְ נַפְשָׁא חֳלַף נַפְשָׁא עֵינָא חֳלַף עֵינָא שִׁנָא חֳלַף שִׁנָא יְדָא חֳלַף יְדָא רַגְלָא חֳלַף רַגְלָא:
@69 אֲרֵי תִפּוֹק לַאֲגָחָא קְרָבָא עַל בַּעֲלֵי דְבָבָךְ וְתֶחֱזֵי סוּסָוָן וּרְתִכִּין עַם סַגִי מִנָךְ לָא תִדְחַל מִנְהוֹן אֲרֵי יְיָ אֱלָהָךְ מֵימְרֵהּ בְּסַעְדָךְ דְאַסְקָךְ מֵאַרְעָא דְמִצְרָיִם:
@70 וִיהֵי כְּמִקְרָבְכוֹן לַאֲגָחָא קְרָבָא וְיִתְקְרִיב כַּהֲנָא וִימַלֵל עִם עַמָא:
@71 וְיֵימַר לְהוֹן שְׁמַע יִשְׂרָאֵל אַתּוּן קְרִיבִין יוֹמָא דֵין לַאֲגָחָא קְרָבָא עַל בַּעֲלֵי דְבָבֵיכוֹן לָא יְזוּעַ לִבְּכוֹן לָא תִדְחֲלוּן וְלָא תִתְבַּהֲתוּן וְלָא תִתָּבְרוּן מִקֳדָמֵיהוֹן:
@72 אֲרֵי יְיָ אֱלָהֲכוֹן דִמְדַבַּר קֳדָמֵיכוֹן לַאֲגָחָא לְכוֹן קְרָב עִם בַּעֲלֵי דְבָבֵיכוֹן לְמִפְרַק יָתְכוֹן:
@73 וִימַלְלוּן סָרְכַיָא קֳדָם עַמָא לְמֵימָר מָן גַבְרָא דִי בְנָא בֵיתָא חַדְתָּא וְלָא חָנְכֵהּ יְהַךְ וִיתוּב לְבֵיתֵהּ דִילְמָא יְמוּת בַּאֲגָחָא קְרָבָא וּגְבַר אָחָרָן יַחְנְכִנֵהּ:
@74 וּמָן גַבְרָא דִי נְצִיב כַּרְמָא וְלָא אַחֲלֵהּ יְהַךְ וִיתוּב לְבֵיתֵהּ דִילְמָא יְמוּת בַּאֲגָחָא קְרָבָא וּגְבַר אָחָרָן יְחַלִנֵהּ:
@75 וּמָן גַבְרָא דִי אֵרַס אִתְּתָא וְלָא נָסְבַהּ יְהַךְ וִיתוּב לְבֵיתֵהּ דִילְמָא יְמוּת בַּאֲגָחָא קְרָבָא וּגְבַר אָחֳרָן יִסְבִנַהּ:
@76 וְיוֹסְפוּן סָרְכַיָא לְמַלָלָא עִם עַמָא וְיֵימְרוּן מָן גַבְרָא דְדָחֵל וּתְבִיר לִבָּא יְהַךְ וִיתוּב לְבֵיתֵהּ וְלָא יִתְּבַר יָת לִבָּא דַאַחוֹהִי כְּלִבֵּהּ:
@77 וִיהֵי כַּד יְשֵׁצוּן סָרְכַיָא לְמַלָלָא עִם עַמָא וִימַנוּן רַבָּנֵי חֵילָא בְּרֵישׁ עַמָא:
@78 אֲרֵי תִקְרַב לְקַרְתָּא לַאֲגָחָא (קְרָבָא) עֲלַהּ וְתִקְרֵי לַהּ מִלִין דִשְׁלָם:
@79 וִיהֵי אִם שְׁלַם תַּעֲנִנָךְ וְתִפְתַּח לָךְ וִיהֵי כָּל עַמָא דְיִשְׁתְּכַח בַּהּ יְהוֹן לָךְ מַסְקֵי מִסִין וְיִפְלְחֻנָךְ:
@80 וְאִם לָא תַשְׁלֵם עִמָךְ וְתַעְבֵּד עִמָךְ קְרָב וּתְצוּר עֲלַהּ:
@81 וְיִמְסְרִנַהּ יְיָ אֱלָהָךְ בִּידָךְ וְתִמְחֵי יָת כָּל דְכוּרַהּ לְפִתְגַם דְחָרֶב:
@82 לְחוֹד נְשַׁיָא וְטַפְלָא וּבְעִירָא וְכֹל דִי יְהֵי בְקַרְתָּא כָּל עֲדָאַהּ תֵּבוֹז לָךְ וְתֵיכוּל יָת עֲדָאָה דְסַנְאָךְ דִי יְהַב יְיָ אֱלָהָךְ לָךְ:
@83 כֵּן תַּעְבֵד לְכָל קִרְוַיָא דִי רְחִיקִין מִנָךְ לַחֲדָא דִי לָא מִקִרְוֵי עַמְמַיָא הָאִלֵין אִנוּן:
@84 לְחוֹד מִקִרְוֵי עַמְמַיָא הָאִלֵין דִי יְיָ אֱלָהָךְ יָהֵב לָךְ אַחֲסָנָא לָא תְקַיַם כָּל נִשְׁמָתָא:
@85 אֲרֵי גַמָרָא תְגַמְרִנוּן חִתָּאֵי וֶאֱמֹרָאֵי כְּנַעֲנָאֵי וּפְרִזָאֵי חִוָאֵי וִיבוּסָאֵי כְּמָא דִי פַקְדָךְ יְיָ אֱלָהָךְ:
@86 בְּדִיל דִי לָא יַלְפוּן יָתְכוֹן לְמֶעְבַּד כְּכָל תּוֹעֲבָתְהוֹן דִי עֲבָדוּ לְטַעֲוָתְהוֹן וּתְחוֹבוּן קֳדָם יְיָ אֱלָהֲכוֹן:
@87 אֲרֵי תְצוּר לְקַרְתָּא יוֹמִין סַגִיאִין לַאֲגָחָא עֲלַהּ לְמִכְבְּשַׁהּ לָא תְחַבֵּל יָת אִילָנַהּ לַאֲרָמָא עֲלוֹהִי פַּרְזְלָא אֲרֵי מִנֵה תֵּיכוּל וְיָתֵהּ לָא תְקוּץ אֲרֵי לָא כַאֲנָשָׁא אִילַן חַקְלָא לְמֵיעַל מְקָדָמָךְ בִּצְיָרָא:
@88 לְחוֹד אִילָן דְתִדַע אֲרֵי לָא אִילַן דְמַאֲכָל הוּא יָתֵהּ תְּחַבַּל וּתְקוּץ וְתִבְנֵי כַרְקוֹמִין עַל קַרְתָּא דִי הִיא עָבְדָא עִמָךְ קְרָבָא עַד דְתִכְבְּשַׁהּ:
@89 אֲרֵי יִשְׁתְּכַח קְטִּילָא בְּאַרְעָא דִי יְיָ אֱלָהָךְ יָהֵב לָךְ לְמֵירְתַהּ רָמֵי בְּחַקְלָא לָא אִתְיְדַע מַן קָטְּלֵהּ:
@90 וְיִפְּקוּן סָבָיךְ וְדַיָנָיךְ וְיִמְשְׁחוּן לְקִרְוַיָא דִי סַחֲרָנוּת קְטִילָא:
@91 וּתְהֵי קַרְתָּא דִקְרִיבָא לִקְטִילָא וְיִדְבְּרוּן סָבֵי קַרְתָּא הַהִיא עֶגְלַת תּוֹרֵי דִי לָא אִתְפְּלַח בַּהּ דִי לָא נְגִידַת בְּנוּר:
@92 וְיֶחֱתוּן סָבֵי קַרְתָּא הַהִיא יָת עֲגַלְתָּא לְנַחֲלָא בַיָר דִי לָא יִתְפְּלַח בֵּהּ וְלָא יִזְדְרַע וְיִנְקְפוּן תַּמָן יָת עֲגַלְתָּא בְּנַחֲלָא:
@93 וְיִתְקָרְבוּן כָּהֲנַיָא בְּנֵי לֵוִי אֲרֵי בְהוֹן יִתִּרְעֵי יְיָ אֱלָהָךְ לְשַׁמָשׁוּתֵהּ וּלְבָרָכָא בִּשְׁמָא דַיְיָ וְעַל מֵימְרֵהוֹן יְהֵי כָּל דִין וְכָל מַכְתַּשׁ סְגִירוּ:
@94 וְכֹל סָבֵי קַרְתָּא הַהִיא דִקְרִיבִין לִקְטִילָא יַסְחוּן יָת יְדֵיהוֹן עַל עֲגַלְתָּא דִנְקֶפְתָּא בְנַחֲלָא:
@95 וִיתִיבוּן וְיֵימְרוּן יְדָנָא לָא אַשְׁדוֹ יָת דְמָא הָדֵין וְעֵינָנָא לָא חֲזָאָה:
@96 כָּהֲנַיָא יֵימְרוּן כַּפַּר לְעַמָךְ יִשְׂרָאֵל דִי פְרַקְתָּא יְיָ וְלָא תִתֵּן חוֹבַת דַם זַכַּי בְּגוֹ עַמָךְ יִשְׂרָאֵל וְיִתְכַּפַּר לְהוֹן עַל דְמָא:
@97 וְאַתְּ תְּפַלֵי אַשְׁדִי דַם זַכַּי מִבֵּינָךְ אֲרֵי תַעְבֵּד דְכָשַׁר קֳדָם יְיָ: ססס:

@1 **שפטים ושטרים.** שופטים, דינים הפוסקים את הדין. ושוטרים, הרודין את העם אחר מצותם. שמכין וכופתין במקל וברצועה עד שיקבל עליו את דין השופט: **בכל שעריך.** בכל עיר ועיר: **לשבטיך.** מוסב על תתן לך. שופטים ושוטרים תתן לך לשבטיך בכל שעריך אשר ה' אלהיך נתן לך: **לשבטיך.** מלמד שמושיבין דינין לכל שבט ושבט ובכל עיר ועיר: **ושפטו את העם** וגו' **.** מנה דינין מומחים וצדיקים לשפוט צדק:
@2 **לא תטה משפט.** כמשמעו: **לא תכיר פנים.** אף בשעת הטענות. אזהרה לדין שלא יהא רך לזה וקשה לזה, אחד עומד ואחד יושב. לפי שכשרואה שהדין מכבד את חברו מסתתמין טענותיו: **ולא תקח שחד.** אפלו לשפוט צדק: **כי השחד יעור.** משקבל שחד ממנו אי אפשר שלא יטה את לבו אצלו להפוך בזכותו: **דברי צדיקים.** דברים המצדקים, משפטי אמת:
@3 **צדק צדק תרדף.** הלך אחר בית דין יפה: **למען תחיה וירשת.** כדאי הוא מנוי הדינין הכשרים להחיות את ישראל ולהושיבן על אדמתן:
@4 **לא תטע לך אשרה.** לחייבו עליה משעת נטיעתה ואפלו לא עבדה עובר בלא תעשה על נטיעתה: **לא תטע לך אשרה כל עץ אצל מזבח ה' אלהיך.** אזהרה לנוטע אילן ולבונה בית בהר הבית:
@5 **ולא תקים לך מצבה.** מצבת אבן אחת, להקריב עליה אפלו לשמים: **אשר שנא.** מזבח אבנים ומזבח אדמה צוה לעשות, ואת זו שנא כי חק היתה לכנענים. ואף על פי שהיתה אהובה לו בימי האבות, עכשיו שנאה, מאחר שעשאוה אלו חק לעבודה זרה:
@6 **לא תזבח** וגו' **כל דבר רע.** אזהרה למפגל בקדשים על ידי דבור רע. ועוד נדרשו בו שאר דרשות בשחיטת קדשים:
@7 **לעבר בריתו.** אשר כרת אתכם שלא לעבוד עבודה זרה:
@8 **אשר לא צויתי.** לעבדם:
@9 **נכון.** מכון העדות:
@10 **והוצאת את האיש ההוא:. אל שעריך** וגו' **.** המתרגם אל שעריך, לתרע בית דינך, טועה, שכן שנינו אל שעריך זה שער שעבד בו, או אינו אלא שער שנדון בו, נאמר שעריך למטה ונאמר שעריך למעלה (פסוק ב) מה שעריך האמור למעלה שער שעבד בו אף שעריך האמור למטה שער שעבד בו. ותרגומו לקרוך:
@11 **שנים [עדים] או שלשה.** אם מתקימת עדות בשנים למה פרט לך בשלשה, להקיש שלשה לשנים, מה שנים עדות אחת, אף שלשה עדות אחת, ואין נעשין זוממין עד שיזומו כלם:
@13 **כי יפלא.** כל הפלאה לשון הבדלה ופרישה, שהדבר נבדל ומכסה ממך: **בין דם לדם.** בין דם טמא לדם טהור: **בין דין לדין.** בין דין זכאי לדין חיב: **בין נגע לנגע.** בין נגע טמא לנגע טהור: **דברי ריבת.** שיהו חכמי העיר חולקים בדבר, זה מטמא וזה מטהר זה מחיב וזה מזכה: **וקמת ועלית.** מלמד שבית המקדש גבוה מכל המקומות:
@14 **הכהנים הלוים.** הכהנים שיצאו משבט לוי: **ואל השפט אשר יהיה בימים ההם.** ואפלו אינו כשאר שופטים שהיו לפניו אתה צריך לשמוע לו. אין לך אלא שופט שבימיך:
@16 **ימין ושמאל.** אפלו אומר לך על ימין שהוא שמאל ועל שמאל שהוא ימין, וכל שכן שאומר לך על ימין ימין ועל שמאל שמאל:
@18 **וכל העם ישמעו.** מכאן שממתינין לו עד הרגל וממיתין אותו ברגל:
@21 **לא ירבה לו סוסים.** אלא כדי מרכבתו, שלא ישיב את העם מצרימה, שהסוסים באים משם. כמה שנאמר בשלמה, ותעלה ותצא מרכבה ממצרים בשש מאות כסף וסוס בחמשים ומאה (מלכים א' י, כט) :
@22 **ולא ירבה לו נשים.** אלא שמונה עשרה, שמצינו שהיו לו לדוד שש נשים, ונאמר לו ואם מעט ואספה לך כהנה וכהנה (שמואל ב' יב, ח) : **וכסף וזהב לא ירבה לו מאד.** אלא כדי לתן לאכסניא [לאפסניא] :
@23 **והיה כשבתו.** אם עשה כן, כדאי הוא שתתקיים מלכותו: **את משנה התורה.** שתי ספרי תורה. אחת שהיא מנחת בבית גנזיו ואחת שנכנסת ויוצאת עמו. ואונקלוס תרגם פתשגן, פתר משנה לשון שנון ודבור:
@24 **דברי התורה.** כמשמעו:
@25 **ולבלתי סור מן המצוה.** אפלו מצוה קלה של נביא: **למען יאריך ימים.** מכלל הן אתה שומע לאו. וכן מצינו בשאול שאמר לו שמואל שבעת ימים תוחל עד בואי אליך להעלות עלות (שמואל א' י, ח) וכתיב ויוחל שבעת ימים (שמואל א' יג, ח) ולא שמר הבטחתו לשמור כל היום, ולא הספיק להעלות העולה עד שבא שמואל ואמר לו נסכלת לא שמרת וגו' ועתה ממלכתך לא תקום (שם יג ז. יד) . הא למדת, שבשביל מצוה קלה של נביא נענש: **הוא ובניו.** מגיד שאם בנו הגון למלכות הוא קודם לכל אדם:
@27 **כל שבט לוי.** בין תמימין בין בעלי מומין: **חלק.** בבזה: **ונחלה.** בארץ: **אשי ה'.** קדשי המקדש [הקדשים] : **ונחלתו.** אלו קדשי הגבול תרומות ומעשרות. אבל נחלה גמורה לא יהיה לו בקרב אחיו. ובספרי דרשו, ונחלה לא יהיה לו. זו נחלת שאר: **בקרב אחיו.** זו נחלת חמשה. ואיני יודע מה היא. ונראה לי שארץ כנען שמעבר הירדן ואלך נקראת ארץ חמשה עממין, ושל סיחון ועוג, שני עממין אמורי וכנעני. ונחלת שאר לרבות קיני וקנזי וקדמוני. וכן דורש בפרשת מתנות שנאמרו לאהרן על כן לא היה ללוי וגו' (דברים י, ט) להזהיר על קיני וקנזי וקדמוני. שוב נמצא בדברי רבי קלונימוס הכי גרסינן בספרי ונחלה לא יהיה לו אלו נחלת חמשה. בקרב אחיו אלו נחלת שבעה. נחלת חמשה שבטים ונחלת שבעה שבטים. ומתוך שמשה ויהושע לא חלקו נחלה אלא לחמשה שבטים בלבד, שכן משה הנחיל לראובן וגד וחצי שבט מנשה, ויהושע הנחיל ליהודה ואפרים ולחצי שבט מנשה, ושבעה האחרים נטלו מאליהן אחרי מות יהושע, מתוך כך הזכיר חמשה לבד ושבעה לבד: **כאשר דבר לו.** לאהרן, בארצם לא תנחל וגו' אני חלקך (במדבר יח, כ) :
@28 **מאת העם.** ולא מאת הכהנים: **אם שור אם שה.** פרט לחיה: **הזרוע.** מן הפרק של ארכבה עד כף של יד שקורין אשפלדו''ן [עצם השכם] : **והלחיים.** עם הלשון. דורשי רשומות היו אומרים, זרוע, תחת יד, שנאמר (במדבר כה, ז) ויקח רמח בידו. לחיים, תחת תפלה, שנאמר (תהל' קו, ל) ויעמד פינחס ויפלל: **והקבה.** תחת (במד' כה) האשה אל קבתה:
@29 **ראשית דגנך.** זו תרומה, ולא פרש בה שעור, אבל רבותינו נתנו בה שעור, עין יפה אחד מארבעים, עין רעה אחד מששים, בינונית אחד מחמשים. וסמכו על המקרא שלא לפחות מאחד מששים, שנאמר וששיתם האיפה מחמר השערים (יחזקאל מה, יג) ששית האיפה, חצי סאה. כשאתה נותן חצי סאה לכור, הרי אחד מששים, שהכור שלשים סאין: **וראשית גז צאנך.** כשאתה גוזז צאנך בכל שנה תן ממנה ראשית לכהן. ולא פרש בה שעור. ורבותינו נתנו בה שעור אחד מששים. וכמה צאן חיבות בראשית הגז, חמש רחלות, שנאמר (שמואל א' כה, יח) וחמש צאן עשויות. רבי עקיבא אומר ראשית גז שתים, גז צאנך ארבע, תתן לו הרי חמש:
@30 **לעמד לשרת.** מכאן שאין שרות אלא מעומד:
@32 **וכי יבא הלוי.** יכול בבן לוי ודאי הכתוב מדבר, תלמוד לומר ושרת, יצאו לויים שאין ראויין לשרות: **ובא בכל אות נפשו** וגו' **ושרת.** למד על הכהן שבא ומקריב קרבנות נדבתו או חובתו ואפלו במשמר שאינו שלו. דבר אחר עוד למד על הכהנים הבאים לרגל שמקריבין במשמר ועובדין בקרבנות הבאים מחמת הרגל, כגון מוספי הרגל, ואף על פי שאין המשמר שלהם:
@33 **חלק כחלק יאכלו.** מלמד שחולקין בעורות ובבשר שעירי חטאות. יכול אף בדברים הבאים שלא מחמת הרגל, כגון תמידין ומוספי שבת ונדרים ונדבות, תלמוד לומר לבד ממכריו על האבות, חוץ ממה שמכרו האבות בימי דוד ושמואל, שנקבעו המשמרות ומכרו זה לזה טול אתה שבתך ואני אטול שבתי:
@34 **לא תלמד לעשות.** אבל אתה למד להבין ולהורות, כלומר להבין מעשיהם כמה הם מקלקלים, ולהורות לבניך לא תעשה כך וכך, שזה הוא חק הגוים:
@35 **מעביר בנו ובתו באש.** היא עבודת המולך. עושה מדורות אש מכאן ומכאן ומעבירו בין שתיהם: **קסם קסמים.** איזהו קוסם, האוחז את מקלו ואומר אם אלך אם לא אלך. וכן הוא אומר, (הושע ד, יב) עמי בעצו ישאל ומקלו יגיד לו: **מעונן.** רבי עקיבא אומר אלו נותני עונות, שאומרים עונה פלונית יפה להתחיל. וחכמים אומרים אלו אוחזי העינים: **מנחש.** פתו נפלה מפיו, צבי הפסיקו בדרך, מקלו נפל מידו:
@36 **וחבר חבר.** שמצרף נחשים או עקרבים או שאר חיות למקום אחד: **ושאל אוב.** זה מכשפות ששמו פיתום ומדבר משחיו ומעלה את המת בבית השחי שלו: **וידעני.** מכניס עצם חיה ששמה ידוע, לתוך פיו, ומדבר העצם על ידי מכשפות: **ודרש אל המתים.** כגון המעלה בזכרותו והנשאל בגלגלת:
@37 **כל עשה אלה.** עשה כל אלה לא נאמר אלא כל עשה אלה, אפלו אחת מהן:
@38 **תמים תהיה עם ה' אלהיך.** התהלך עמו בתמימות ותצפה לו ולא תחקור אחר העתידות, אלא כל מה שיבא עליך קבל בתמימות ואז תהיה עמו ולחלקו:
@39 **לא כן נתן לך ה' אלהיך.** לשמוע אל מעוננים ואל קוסמים שהרי השרה שכינה על הנביאים ואורים ותמים:
@40 **מקרבך מאחיך כמני.** כמו שאני מקרבך מאחיך יקים לך תחתי, וכן מנביא לנביא:
@45 **אשר לא צויתיו לדבר.** אבל צויתיו לחברו: **ואשר ידבר בשם אלהים אחרים.** אפלו כון את ההלכה, לאסור את האסור ולהתיר את המתר: **ומת.** בחנק. שלשה מיתתן בידי אדם, המתנבא מה שלא שמע ומה שלא נאמר לו ונאמר לחברו, והמתנבא בשם עבודה זרה. אבל הכובש את נבואתו והעובר על דברי נביא והעובר על דברי עצמו מיתתן בידי שמים, שנאמר אנכי אדרש מעמו (פסוק יט) :
@46 **וכי תאמר בלבבך.** עתידין אתם לומר, כשיבא חנניה בן עזור ומתנבא (ירמיה כז, טז) הנה כלי בית ה' מושבים מבבלה עתה מהרה, וירמיהו עומד וצווח על העמודים ועל הים ועל יתר הכלים שלא גלו עם יכניה, (שם כז, כב) בבלה יובאו עם גלות צדקיהו:
@47 **אשר ידבר הנביא.** ויאמר דבר זה עתיד לבא עליכם, ותראו שלא יבא, הוא הדבר אשר לא דברו ה' והרג אותו. ואם תאמר זו במתנבא על העתידות, הרי שבא ואמר עשו כך וכך ומפי הקדוש ברוך הוא אני אומר, כבר נצטוו שאם בא להדיחך מאחת מכל המצות לא תשמע לו, אלא אם כן ממחה הוא לך שהוא צדיק גמור, כגון אליהו בהר הכרמל שהקריב בבמה בשעת אסור הבמות כדי לגדור את ישראל. הכל לפי צורך השעה וסיג הפרצה, לכך נאמר אליו תשמעון: **לא תגור ממנו.** לא תמנע עצמך מללמד עליו חובה ולא תירא לענש עליו:
@50 **תכין לך הדרך.** מקלט מקלט היה כתוב על פרשת דרכים: **ושלשת את גבול ארצך.** שיהא מתחלת הגבול עד העיר הראשונה של עיר מקלט, כשעור מהלך שיש ממנה עד השניה. וכן משניה, לשלישית. וכן מן השלישית, עד הגבול השני של ארץ ישראל:
@52 **ונדחה ידו.** כשבא להפיל הגרזן על העץ, ותרגומו ותתמריג ידיה, לשון ונשמטה ידו להפיל מכת הגרזן על העץ. כי שמטו הבקר, תרגם יונתן (שמואל ב' ו, ו) ארי מרגוהי תוריא: **ונשל הברזל מן העץ.** יש מרבותינו אומרים נשמט הברזל מקתו, ויש מהם אומרים שישיל הברזל חתיכה מן העץ המתבקע, והיא נתזה והרגה:
@53 **פן ירדף גאל הדם.** לכך אני אומר להכין לך דרך, וערי מקלט רבים:
@55 **ואם ירחיב.** כאשר נשבע לתת לך ארץ קיני וקנזי וקדמוני:
@56 **ויספת לך עוד שלש.** הרי תשע. שלש שבעבר הירדן ושלש שבארץ כנען ושלש לעתיד לבא:
@58 **וכי יהיה איש שנא לרעהו.** על ידי שנאתו הוא בא לידי וארב לו. מכאן אמרו עבר אדם על מצוה קלה סופו לעבור על מצוה חמורה. לפי שעבר על לא תשנא, סופו לבא לידי שפיכת דמים. לכך נאמר כי יהיה איש שנא לרעהו וגו' , שהיה לו לכתוב וכי יקום איש וארב לרעהו והכהו נפש:
@60 **לא תחוס עינך.** שלא תאמר הראשון כבר נהרג, למה אנו הורגים את זה ונמצאו שני ישראלים הרוגים:
@61 **לא תסיג גבול.** לשון (ישעיה מב, יז) נסגו אחור, שמחזיר סימן חלקת הקרקע לאחור לתוך שדה חברו למען הרחיב את שלו. והלא כבר נאמר (ויקרא יט, יג) לא תגזל, מה תלמוד לומר לא תסיג, למד על העוקר תחום חברו שעובר בשני לאוין. יכול אף בחוצה לארץ, תלמוד לומר בנחלתך אשר תנחל וגו' , בארץ ישראל עובר בשני לאוין, בחוצה לארץ אינו עובר אלא משום לא תגזל:
@62 **עד אחד.** זה בנה אב. כל עד שבתורה שנים, אלא אם כן פרט לך בו אחד: **לכל עון ולכל חטאת.** להיות חברו נענש על עדותו, לא עונש גוף ולא עונש ממון, אבל קם הוא לשבועה. אמר לחברו תן לי מנה שהלויתיך, אמר לו אין לך בידי כלום, ועד אחד מעיד שיש לו, חיב להשבע לו: **על פי שני עדים.** ולא שיכתבו עדותם באגרת וישלחו לבית דין, ולא שיעמוד תרגמן בין העדים ובין הדינים:
@63 **לענות בו סרה.** דבר שאינו, שהוסר העד הזה מכל העדות הזאת, כגון, שאמרו להם והלא עמנו הייתם אותו היום במקום פלוני:
@64 **ועמדו שני האנשים.** בעדים הכתוב מדבר, ולמד שאין עדות בנשים, ולמד שצריכין להעיד עדותן מעומד: **אשר להם הריב.** אלו בעלי הדין: **לפני ה'.** יהי דומה להם כאלו עומדין לפני המקום, שנאמר (תהלים פב, א) בקרב אלהים ישפט: **אשר יהיו בימים ההם.** יפתח בדורו כשמואל בדורו, צריך אתה לנהוג בו כבוד:
@65 **ודרשו השופטים היטב.** על פי המזימין אותם, שבודקים וחוקרים את הבאים להזימם בדרישה ובחקירה: **והנה עד שקר.** כל מקום שנאמר עד, בשנים הכתוב מדבר:
@66 **כאשר זמם.** ולא כאשר עשה. מכאן אמרו, הרגו אין נהרגין: **לעשות לאחיו.** מה תלמוד לומר לאחיו, למד על זוממי בת כהן נשואה שאינן בשריפה, אלא כמיתת הבועל שהוא בחנק, שנאמר (ויקרא כא, ט) היא באש תשרף, היא ולא בועלה. לכך נאמר כאן לאחיו, כאשר זמם לעשות לאחיו, ולא כאשר זמם לעשות לאחותו. אבל בכל שאר מיתות השוה הכתוב אשה לאיש, וזוממי אשה נהרגין כזוממי איש. כגון שהעידוה שהרגה את הנפש, שחללה את השבת, נהרגין במיתתה. שלא מעט כאן אחותו אלא במקום שיש לקים בהן הזמה במיתת הבועל:
@67 **ישמעו ויראו.** מכאן שצריכין הכרזה, איש פלוני ופלוני נהרגין על שהוזמו בבית דין:
@68 **עין בעין.** ממון, וכן שן בשן וגו' :
@69 **כי תצא למלחמה.** סמך הכתוב יציאת מלחמה לכאן, לומר לך, שאין מחסר אבר יוצא למלחמה. דבר אחר לומר לך, אם עשית משפט צדק אתה מבטח שאם תצא למלחמה אתה נוצח. וכן דוד הוא אומר (תהלים קיט, קכא) עשיתי משפט וצדק בל תניחני לעשקי: **על איבך.** יהיו בעיניך כאויבים, אל תרחם עליהם כי לא ירחמו עליך: **סוס ורכב.** בעיני כלם כסוס אחד, וכן הוא אומר (שופטים ו, טז) והכית את מדין כאיש אחד. וכן הוא אומר (שמות טו, יט) כי בא סוס פרעה: **עם רב ממך.** בעיניך הוא רב, אבל בעיני אינו רב:
@70 **כקרבכם אל המלחמה.** סמוך לצאתכם מן הספר מגבול ארצכם: **ונגש הכהן.** המשוח לכך. והוא הנקרא משוח מלחמה: **ודבר אל העם.** בלשון הקדש:
@71 **שמע ישראל.** אפלו אין בכם זכות אלא קרית שמע בלבד, כדאי אתם שיושיע אתכם: **על איביכם.** אין אלו אחיכם, שאם תפלו בידם אינם מרחמים עליכם, אין זו כמלחמת יהודה עם ישראל, שנאמר (דה''י ב' כח, טו) ויקמו האנשים אשר נקבו בשמות ויחזיקו בשביה, וכל מערמיהם הלבישו מן השלל וילבשום וינעלום ויאכלום וישקום ויסכום וינהלום בחמרים לכל כושל, ויביאום ירחו עיר התמרים אצל אחיהם, וישובו שמרון, אלא על אויביכם אתם הולכים, לפיכך התחזקו למלחמה: **אל ירך לבבכם אל תיראו ואל תחפזו ואל תערצו.** ארבע אזהרות כנגד ארבעה דברים שמלכי האמות עושים. מגיפים בתריסיהם כדי להקישן זה לזה כדי להשמיע קול שיחפזו אלו שכנגדם וינוסו, ורומסים בסוסיהם ומצהילין אותם להשמיע קול שעטת פרסות סוסיהם, וצווחין בקולם ותוקעין בשופרות ומיני משמיעי קול: **אל ירך לבבכם.** מצהלת סוסים: **אל תיראו.** מהגפת התריסין: **ואל תחפזו.** מקול הקרנות: **ואל תערצו.** מקול הצוחה:
@72 **כי ה' אלהיכם** וגו' **.** הם באים בנצחונו של בשר ודם ואתם באים בנצחונו של מקום. פלשתים באו בנצחונו של גלית, מה היה סופו, נפל ונפלו עמו: **ההלך עמכם.** זה מחנה הארון:
@73 **ולא חנכו.** לא דר בו. חנוך לשון התחלה: **ואיש אחר יחנכנו.** ודבר של עגמת נפש הוא זה:
@74 **ולא חללו.** לא פדאו בשנה הרביעית, שהפירות טעונין לאכלן בירושלים או לחללן בדמים ולאכל הדמים בירושלים:
@75 **פן ימות במלחמה.** ישוב פן ימות, שאם לא ישמע לדברי הכהן כדאי הוא שימות:
@76 **ויספו השטרים.** למה נאמר כאן ויספו, מוסיפין זה על דברי הכהן, שהכהן מדבר ומשמיע מן (פסוק ג, ד) שמע ישראל עד להושיע אתכם, ומי האיש ושני ושלישי כהן מדבר ושוטר משמיע, וזה שוטר מדבר ושוטר משמיע: **הירא ורך הלבב.** רבי עקיבא אומר כמשמעו, שאינו יכול לעמוד בקשרי המלחמה ולראות חרב שלופה. רבי יוסי הגלילי אומר הירא מעבירות שבידו, ולכך תלתה לו תורה לחזור על בית וכרם ואשה לכסות על החוזרים בשביל עברות שבידם, שלא יבינו שהם בעלי עברה, והרואהו חוזר אומר שמא בנה בית או נטע כרם או ארש אשה:
@77 **שרי צבאות.** שמעמידין זקפין, מלפניהם ומלאחריהם וכשילין של ברזל בידיהם וכל מי שרוצה לחזור הרשות בידו לקפח את שוקיו. זקפין, בני אדם עומדים בקצה המערכה לזקוף את הנופלים ולחזקם בדברים שובו אל המלחמה ולא תנוסו, שתחלת נפילה ניסה:
@78 **כי תקרב אל עיר.** במלחמת הרשות הכתוב מדבר, כמו שמפורש בענין (פסוק טו) כן תעשה לכל הערים הרחקת וגו' :
@79 **כל העם הנמצא בה.** אפלו אתה מוצא בה משבעה אמות שנצטוית להחרימם, אתה רשאי לקימם: **למס ועבדוך.** עד שיקבלו עליהם מסים ושעבוד:
@80 **ואם לא תשלים עמך ועשתה עמך מלחמה.** הכתוב מבשרך שאם לא תשלים עמך סופה להלחם בך אם תניחנה ותלך: **וצרת עליה.** אף להרעיבה ולהצמיאה ולהמיתה מיתת תחלואים:
@81 **ונתנה ה' אלהיך בידך.** אם עשית כל האמור בענין, סוף שה' נותנה בידך:
@82 **והטף.** אף טף של זכרים. ומה אני מקים (פסוק יג) והכית את כל זכורה, בגדולים:
@85 **כאשר צוך.** לרבות את הגרגשי:
@86 **למען אשר לא ילמדו.** הא אם עשו תשובה ומתגירים, אתה רשאי לקבלם:
@87 **ימים.** שנים: **רבים.** שלשה. מכאן אמרו אין צרין על עירות של נכרים פחות משלשה ימים קודם לשבת. ולמד שפותח בשלום שנים או שלשה ימים. וכן הוא אומר (שמואל ב' א, א) וישב דוד בצקלג ימים שנים, ובמלחמת הרשות הכתוב מדבר: **כי האדם עץ השדה.** הרי כי משמש בלשון דלמא. שמא האדם עץ השדה להכנס בתוך המצור מפניך להתיסר ביסורי רעב וצמא כאנשי העיר, למה תשחיתנו:
@88 **עד רדתה.** לשון רדוי, שתהא כפופה לך:
@90 **ויצאו זקניך.** מיחדים שבזקניך, אלו סנהדרי גדולה: **ומדדו.** ממקום שהחלל שוכב: **אל הערים אשר סביבת החלל.** לכל צד לידע איזו קרובה:
@92 **אל נחל איתן.** קשה, שלא נעבד: **וערפו.** קוצץ ערפה בקופיץ. אמר הקדוש ברוך הוא תבא עגלה בת שנתה שלא עשתה פרות ותערף במקום שאינו עושה פרות, לכפר על הריגתו של זה שלא הניחוהו לעשות פרות:
@95 **ידינו לא שפכה.** וכי עלתה על לב שזקני בית דין שופכי דמים הם, אלא לא ראינוהו ופטרנוהו בלא מזונות ובלא לויה. והכהנים אומרים כפר לעמך ישראל:
@96 **ונכפר להם הדם.** הכתוב מבשרם שמשעשו כן, יכפר להם העון:
@97 **ואתה תבער.** מגיד שאם נמצא ההורג אחר שנתערפה העגלה הרי זה יהרג, והוא הישר בעיני ה':
@98 **מי את.** בת צדיקים כמותך מלאה זכיו' למה תיראי מאנוש אשר סופו למות:
@99 **ותשכח ה' עושך.** ולא נשענת עליו: **המציק.** מושלי אומות העולם המשעבדים בכם: **כאשר כונן.** נזדמן: **ואיה חמת המציק.** מחר בא ואיננו:
@100 **מהר צועה להפתח.** אפי' נקבין קשין עליו וצריך הוא להפתח בהילוך המעים כדי שלא ימות לשחת וכיון שמיהר להפתח צריך הוא למזונות רבים שאם יחסר לחמו אף הוא ימות: **צועה.** ל' דבר העומד להיו' נירוק כמו שאומר במואב שדימהו הנבי' ליין ( ירמי' מח ) השקט אל שמריו ולא הורק מכלי אל כלי ונא' שם ושלחתי לו צועים וצעהו וכליו יריקו, ד"א מהר צועה אותו האויב המציק שהוא עכשיו חגור מתני' חלוץ כח ימהר להפתח ולהיות חלש: **צועה.** חוגר כמו ( לקמן סג ) צועה ברוב כחו. **ולא ימות.** המסור בידו לשחת אבל הלשון ראשון מדר' אגד' הוא בפסיקת' רבתי:
@101 **רוגע הים.** לשון עורי רגע ( איוב ז ) פרונצ"א בלע"ז:
@102 **לנטוע שמים.** לקיימא עמא דאמיר עליהון דיסגון ככוכבי שמיא: **וליסוד ארץ.** ולשכללא כנישתא דאמיר עליהון דיסגון כעפרא דארעא:
@103 **קבעת.** ת"י פילי והוא שם כוס ולי נראה קבעת אלו השמרים הקבועים בתחתית הכלי ומצית יורה עליו כמה שנאמר שמריה ימצו ( תהלים עה ): **התרעלה.** הוא משקה המטמטם ומתיש כח האדם כאסור וקשור ומעוטף כמו הברושים הרעלו ( נחום ב ) והשרות והרעלות שהוא לשון עיטוף ובמס' שבת מדיות רעולו' מין סרבל נאה להתעטף בו. **תרעלה.** אינטומישמנ"ט בלע"ז: **מצית.** אגושטי"ר בלע"ז:
@105 **שתים הנה קראתיך.** צרות כפולות שתים שתים: **מי אנחמך.** מי אביא לך לנחמך ולומר אף אומה פלונית היא לקתה דוגמתך:
@106 **עולפו.** לשון עייפות כמו ( עמוס ח ) תתעלפנה הבתולות בצמא פשמי"ר בלע"ז. כתוא מכמר. הפקר כתוא זה שנפל למכמר, תוא כמו ותאו וזמר ( דברי' יד ):
@107 **ושכורת ולא מיין.** שכורת מדבר אחר שלא מיין:
@108 **יריב עמו.** אשר ידין דין עמו:
@109 **מוגיך.** מניעיך ומטלטליך כמו והנה ההמון נמוג ( ש"א יד ) קרושלי"ר בלע"ז. **שחי ונעבורה.** על גביך:
@111 **התנערי.** אישקור"א בלעז כמנער את הטלית: **קומי.** מן הארץ מגזרת לארץ תשב ( לעיל ג ): **שבי.** על הכסא: **התפתחי.** הוי נתרת: **מוסרי.** קריגל"ש בלע"ז: **שביה.** כמו שבויה:
@112 **חנם נמכרתם.** על עסקי חנם הוא יצר הרע שאינו לכם לשכר: **ולא בכסף תגאלו.** אלא בתשובה:
@113 **מצרים ירד עמו וגו'.** הם המצריים היו להם קצת חוב עליהם שנעשו להם אכסניא וכלכלו' אבל אשור באפס ובחנ' עשקו:
@114 **מה לי פה.** למה אני שוהא ומשהא בני כאן: **יהילילו.** מתפארים לאמר ידינו רמה: **מנואץ.** מתנאץ והרי זה דוגמת וישמע את הקול מדבר אליו ( במדבר ח ):
@115 **ידע עמי.** כשאגאלם יכירו כי שמי אדון שליט ומושל כמשמעו: **לכן ביום.** גאולתם יבינו כי אני הוא המדבר והנני קיימתי:
@117 **צופיך.** צופים שמעמידין על החומות והמגדלים לבשר ולראות מי בא לעיר:
@119 **חשף.** גלה:
@120 **צאו מתוכה.** מתוך הגלות כל נחמות האלו האחרונות אינן אלא על גלות האחרון: **טמא.** אל תגעו, שקץ יהיו לכם מליג' בהם: **הברו.** הטהרו: **נושאי כלי ה'.** הכהנים הלוים שהיית' נושאי' כליו ( של הקב"ה ) במדבר ( מכאן לתחיי' המתים ):
@121 **כי הולך לפניכם.** שני דברים שבסוף המקרא הזה מיישבין שני דברים שבראשו. כי לא בחפזון תצאו. מה טעם, כי הולך לפניכם ה' לנחותכם הדרך ומי ששלוחו מקדים לפניו לנחותו הדרך אין יציאתו בחפזון. ובמנוסה לא תלכון. לפי שמאסיפכם אלהי ישראל הולך מאחריכם לשמור אתכם מכל רודף כמו ונסע דגל מחנה דן מאסף לכל המחנות ההולך אחרי המחנה קרוי מאסף לפי שהוא ממתין את הנחלשים ואת הנכשלים וכן הוא אומר ביהושע והמאסף הולך אחרי הארון:

@1 **שופטים.** אלו דיינים:
@1 **ושוטרים.** אלו הרודים בעם שיש לה' מקל ורצועה להביאם לבית דין ולהנהיגם על פי המשפט אשר יאמרו השופטים:
@1 **תתן לך בכל שעריך.** מגיד שבכל עיר ועיר חייבין למנות שפטים ושוטרים:
@1 **אשר יי' אלהיך נותן לך לשבטיך.** מגיד שבארץ ישראל לבד תנהג המצוה הזאת ואר לשבטיך להעיר שראוי שימנו אלו השופטים מי שהם על כל השבטים והם ימנו שפטים ושוטרים בכל עיר ועיר וימנו שופטים ושטרים בכל שבט ושבט שיהיו על השופטים שבכל שער ושער אשר תחתיהם ויעיד על אמתת זה כי משה מנה השופטים כלם והשוטרים לשבטים כמו שנתבאר בפרשת ואלה הדברים:
@1 **ושפטו את העם משפט צדק.** למדנו מזה שראוי שיהיו אלו השופטים באופן מהחכמה שיהיו ראויים לשפוט את העם משפט צדק ואם לא אין ראוי למנותם ולפי שהמשפט הוא בדיני ממונות ובדיני נפשות כבר ביארנו שהמשפט אשר יהיה בדיני נפשות לא ישלם וכי אם בבית דין של כ"ג והתבאר בזה המקום שכל משפט יצטרכו שופטים והם שנים שנאמר שופטים ושוטרים ומעוט רבים הם שנים ואין ראוי שיהיה בית דין שקול ולזה יוסיפו עליהם אחד והם ג' הנה אם יהיו בעיר ראויים למנות מהם כ"ג שיוכלו לשפוט את העם משפט צדק בדיני נפשות ממנים אותם שם ואם לא הנה ימנו שם בית דין של שלשה אם היו שם ראויים לשפוט צדק בדיני ממונות:
@2 **לא תטה משפט.** רוצה לומר לא תהיה סבה בזה המנוי להטו' משפט וזה יהיה אם תמנה מי שאינו ראוי לשפוט':
@2 **לא תכיר פנים.** רוצה לומר לא תכיר פנים בזה המנוי למנות אדם מפני שהוא קרובך או אהובך או לזולת זה מהסיבות כשלא היה המנוי מצד היותו ראוי לשפוט:
@2 **לא תקח שוחד.** בזה המנוי גם למנו' הראוי לשפוט וזה כי השוחד יעלים ממך זאת הבחינה כי הוא מעור עיני חכמים ומסיר מהם ראות הלב ומעות הדברים הישרים הראוים לצאת מן הצדיקים לפי שלזאת הסבה ימנע מלומר בבלתי ראוי שהוא בלתי ראוי מפני פתוי השוחד:
@3 **צדק צדק תרדוף.** רוצה לומר הוי רץ אחר בית דין יפה שיוכל לשפוט צדק ורדוף הצדק והיושר בכל הדברים כי זה ממה שיגיעך אל החיים הנצחיים ויביאך לירושת הארץ. רוצה לומר להתמיד ולהאריך ישיבתך עליו:
@4 **לא תטע לך אשרה כל עץ.** הזהיר בזה מליטע אשרה אי זה אילן שיהיה אצל מזבח השם יתעלה אף על פי שלא יכוון בה לעבודה זרה לפי שזה היה דרך עובדי עבודה זרה לנטוע אילן אצל מזבחותיהם להתקבץ שם העם ולפי שהזהיר על נטיעת אשרה אפילו לעבודת השם יתעלה הנה הדברים קל וחומר שהוזהרנו מליטע אשרה לעבודה זרה ואפשר עוד שרמז בכאן אל שתי אלו האזהרות ולזה הוציאו בלשון אשרה ויהיה הרצון בזה לא תטע לך אשרה כל עץ אצל מזבח ה' אלהיך והכונה בזה לא תטע לך אשרה בשום מקום ולזה אמר לך כמו שביארנו באמרו אלהי זהב לא תעשו לכם שהכונה בו חוץ מהמקדש. ולא תטע לך אשר כל עץ אצל מזבח ה' אלהיך והכונה בזה לא תטע לך אשרה בשום מקום ולזה אמר לך כמו שביארנו באמרו אלהי זהב לא תעשו לכם שהכונה בו חוץ מהמקדש. ולא תטע לך אשרה כל עץ אצל מזבח ה' אלהיך אשר תעשה. מגיד שהמזבח אשר תעשה לך לה' והוא במת יחיד יהיה אסור גם כן לטעת אצלו כל עץ:
@5 **ולא תקים לך מצבה אשר שנא ה' אלהיך.** הנה ענין המצבה הוא בניין שהכל מתקבצים שם והנה הזהיר מהקמתה אפילו לעבוד השם יתעלה כל שכן לעבודה זרה לפי שכן היה דרך עובדי עבודה זרה לעשות אצל עבודה זרה:
@6 **לא תזבח להש' אלהיך שור ושה אשר יהיה בו מום.** הזהיר בזה שלא לזבוח לשם יתע' בעל מום אף על פי שהוא מום עובר כמו גרב לח ומה שידמה לו:
@6 **כל דבר רע כי תועבת ה' אלהיך הוא.** הרצון בזה שאף על פי שלא היה בו מום כיון שיש בו דבר רע הוא תועבת הש' יתע' כמו אתנן זונה ומחיר כלב ומוקצה לעבודה זרה ועובד ורובע ונרבע הזוכה אותו לה' עובר בלא תעשה:
@7 **כי ימצא בקרבך באחד שעריך והוגד לך ושמעת ודרשת היטב.** מגיד שצריך לדרוש ולחקור בזה מאד אם הענין אמת אם לא:
@9 **והנה אמת נכון הדבר.** רוצה לומר שאחר החקירות והבדיקות נמצא שעדות העדים מכוון:
@10 **והוצאת את האיש ההוא או את האשה ההיא אל שעריך.** רוצה לומר שיביאם להשפט לפני השפטים אשר בערים כי לא יצטרך להביא זה הענין לפני בית דין הגדול שבמקום הבחירה כי איננו דבר גדול וזה שהדבר גדול ראוי שיבא לפני סנהדרי גדולה כמו שמצאנו בשופטים ששם משה על ישראל שלא נתן להם כח בדבר גדול כי היו מביאים אותו אל משה והוא היה סנהדרי גדולה עם שבעים איש שהיו עמו שנ' אספה לי שבעים איש מזקני ישר' ומזה המקום למדנו שהיחידים נדונין בסנהדרי קטנה לא העיר כלה ומזה המקום יתבאר שעיר הנדחת היו דנין אותה סנהדרי גדולה וזה שאיש ואשה אתה מוציא אל שעריך לא כל עיר או רובה:
@10 **וסקלתם באבנים ומתו.** ראוי שתדע שזאת הסקילה תהיה בעיר שנמצאו כמו שמצאנו בנערה המאורשה ובכלל הנה בזה האופן יגיע התועלת לבני העיר שצמח זה הרע בתוכם ונוסרו הנשארים והנה אמר ומתו כי כבר תקרא סקילה אף על פי שאין שם מיתה כאמרו ויסקל באבנים ועפר בעפר:
@11 **על פי שנים עדים או שלשה עדים יומת המת.** הזהיר בזה המקום שלא נענש למות על פי עד אחד כי אם על פי שנים עדים או יותר והנה אמר או שלשה עדים להודיע כי כמו שנרבה בדרישות וחקירות ובדיקות אם היו שני עדים כן נרבה בהם אם היו יותר משנים ולא נאמר כיון שהסכימו רבים בזה העדות הנה הוא אמת ואפילו הן מאה או אלף והנה הקיש שנים לשלשה אם היו שם כתות מכחישות זו את זו הרי השנים כשלשה והשלשה כשנים אפילו הן אלף ובצד אחר גם כן שכמו ששני עדים אם ימצא אחד מהם רשע או חומס או אחד מהדברים שיפסל העד בעבורו עדותן בטלה כן הענין אם היו שלשה או יותר בעדות אחד ובאו להעיד עליו:
@12 **יד העדים תהיה בו בראשונה להמיתו.** ביאר בזה שבאבן שישליכו בו כל אחד מהעדים ראוי שיהיה כדי להמית או אם ירה יירה יהיה בהשלכה כדי להמית ואם לא מת בירייה ההיא ישליך עליו העד השני אם יש בה כדי להמית במקום שימות בו בקלות יותר כמו שהתבאר בשרשים הכוללים ואם לא מת בזה תהיה בו יד כל העם באחרונה זה אחר זה עד שימות ואמנם צותה התור' שתהיה בו בראשונה יד העדים כדי שידקדקו יותר בעדותן שיהיה אמתי שאם היה שקר יקשה להם זה יותר מהעדה בשקר כמו שזכרנו במה שקדם:
@13 **כי יפלא ממך דבר למשפט.** למדנו שהוא מדבר בחכם שנעלם ממנו דבר מה למשפט ממשפטי התורה. וזה שמי שאינו יודע דבר לא יאמר עליו שכבר נעלם ממנו אחד מדיני התורה אבל יאמר זה בעצמו' במי שיודע השא' וכ"ש בזה המקו' שלא אמר שיעלם ממנו המשפט ההוא אבל דבר מה ממנו והכונה בזה המאמר שיהיה מחלוקת בשעריך מאחד מהשופטים אשר יש שם עם חביריו או מקצתן עם קצת בדרך שיפלא ממך בשעריך דבר למשפט ולא יוכל להתברר שם:
@13 **בין דם לדם.** הנה המחלוקת היה בין דם לדם הוא שיאמרו קצתם שזה הדם טמא באשה מצד מראהו וקצתם יאמרו שהוא טהור כי אין לו מראה הדם הטמא או שיאמר קצת שהוא דם טהור כאלו תאמר שתהיה שופעת מתוך ארבעים לאחר מ' או מתוך שמונים לאחר שמנים וקצתם יאמרו שהוא דם טמא כי הימים גורמים והתורה טמאהו אחר ימי מלאת או שיאמר קצתם שהוא דם זיבה וקצתם יאמרו שהוא דם נדה או דם לידה כי זמני טומאתה חלוקים:
@13 **בין דין לדין.** כאלו תאמר שנחלקו בשומ' משכון אם יש לו דין שומר חנם או שומר שכר וכן במה שידמה לזה:
@13 **בין נגע לנגע.** שנחלקו בדבר הנגעים שקצתם יאמרו שזה הנגע הוא טמא מפני שעזרו או מפני מראהו ויאמרו קצתם שהוא טהור כי אין לו שיעור הנגע הטמא או שאין לו המראה הטמא ויהיה המחלוקת ביניהם בשעור הראוי לנגע הטמא או במראהו וכן מה שידמה לזה והיה מפני זה דברי ריבות בשעריך ומחלוקת שזה אומר כך וזה אומר כך:
@13 **וקמת ועלית אל המקום אשר יבחר ה'.** למדנו מזה שבמקום הבחיר' היו יושבי' סנהדרי גדולה הכוללת לכל ישראל שהיא על כל הסנהדרין שיש בכל שער ושער:
@14 **ובאת את הכהנים והלוים.** לפי שנאמר בהם יורו משפטיך ליעקב ותורתך לישראל אמר תחלה הכהנים הלוים כי מהם ראוי לבחור לסנהדרי גדולה אם יש בהם ראוים לזה:
@14 **ואל השופט אשר יהיה בימים ההם.** רוצה לומר או אל השופט שיהיה בימים ההם והרצון בזה אף על פי שלא היה כהן ולא לוי ואמר שיהיה בימים ההם שיהיה אז ראוי להיות שופט לפי הדור ההוא ואף על פי שלא היה ראוי לפי דורות אחרים:
@14 **ודרשת והגידו לך את דבר המשפט.** תדרוש עמהם ותחקור מהם להודיע להם המחלוקת במה שהוא ובאיזה טעם נתלה כל אחד מהם. והם יגידו לך את דבר המשפט לפי הנראה להם אם מהקבלה אם מהסברא:
@15 **ועשית על פי הדבר אשר יגידו לך מן המקום ההוא.** צוה כאן לעשות בהוראה הזאת לפי מה שהסכימו ב"ד הגדול שבמקום הבחירה ולפי שלא היה צריך לומר מן המקום ההוא למדנו מזה שאם יצאו מן המקום ההוא והגידו לא חוייב לשמוע לדבריהם ומי שעבר על דבריהם אינו חייב מיתה כי התורה דקדקה שיגידו זה מהמקום ההוא:
@15 **ושמרת לעשות ככל אשר יורוך.** מגיד שאנחנו מחוייבי' להמשך בדבריהם כדברי התורה ובכל מה שיתבארו ממנה ולזה אמר ככל אשר יורוך:
@16 **לא תסור מן הדבר אשר יגידו לך ימין ושמאל.** הזהיר בכאן מעבור על דבריהם וביאורם לדברי התורה אפילו לאסור מה שהתירו או לטמא מה שטהרו וכל שכן להתיר מה שאסרו או לטהר מה שטמאו ולפי שאמר ועשית על פי הדבר ושמרת לעשות אשר יאמרו לך תעשה למדנו שאינו מחוייב ללמוד לתלמידיו כמו שיאמרו בית דין הגדול אך כשיורה הוראה למעשה יחוייב לו להורות על פי התורה אשר הורו סנהדרי גדולה:
@17 **והאיש אשר יעשה בזדון לבלתי שמוע אל הכהן.** על הוראה למעשה הוא חייב לא על למוד והוראה לתלמידיו לא למעשה ולזה אמר אשר יעשה ועל זדון הוא חייב ואינו חייב אם בשוגג הורה למעשה הוראה זו ולזה אמר בזדון ועל מה ששמע מהסנהדרין ההוא הוא חייב לא אם שמע מפי שומע והנה אמר הכהן או השופט כי המופלא שבבית דין והוא מי שהוא ראש עליהם הוא אשר יאמר לו מה שיסכימו בו סנהדרי גדולה כי אין ראוי שיגמ' הדבר כי אם על פיו:
@17 **העומד לשרת שם את פני יי' אלהיך.** למדנו מזה שמקום סנהדרין היה אצל בית הבחירה אשר ישרתו שם השם יתעלה למדנו מאמרו העומד לשרת שהשירות לא יהיה אלא בעמידה:
@17 **ומת האיש ההוא.** זאת המית' חנק הוא לפי מה שתתבאר מהשרשים הכוללים אחר שהתבאר שכבר עשה זה בזדון:
@17 **ובערת הרע מקרבך.** אמר זה לפי שזה המחלוקת יהיה גורם להריסת התורה אם ישפוט בה כל איש לפי דעתו וסברתו ולזה יסדה התורה זה השרש להסיר המחלוקת מענייני התורה בדור ודור ולפי שהאיש ההוא הוא יחיד דנין אותו למיתה בית דין שבעירו אחר החקירה והדרישה ולפי שאמר וכל העם ישמעו וייראו רוצה לומר שכלם ישמעו דבר זה הדין הנפלא וייראו מעשו' כך ולמדנו מזה שמעלין אותו למקום הבחירה ומשהין אותו עד הרגל שיעלו שם הכל ואז יתכן שישמעו זה כל העם וכן הענין במסית שהרי נאמר בו וכל ישראל ישמעו וייראו ולא יזידון עוד רוצה לומר שלא יזידו השופטים להורות לעשות כך כנגד הוראת בית דין הגדול והנה מפני שמצאנו בפרטים שזכרה התורה שהיה בהם המחלוקת שבכלם משתתפים כשיש בהם צד אל שיביאם המחלוקת לדבר שחייבם על זדונם כרת ועל שגגתו חטאת והיה מבואר שאין ראוי שנתן זה הדין החמור למה שהוא קל מהם בזה הענין הנה אם לא היה המחלוקת אשר ביניהם מבוא בשום צד לחטוא בדבר שחייבין על זדונם כרת ועל שגגתו חטאת אין זקן ממרא חייב מיתה עליו אם הורה לעשו' כהוראתו וזה דבר מבואר מהשרשים הכוללים והמשל שאם היה המחלוקת בצציות או בכלאי הכרם או בלולב או בשופר או בסכה ומה שידמה לזה שאין לו מבוא בשום פנים להביא אל חטא שחייבין על זדונו כרת ועל שגגתו חטאת לא יהיה חייב מיתה אם הורה לעשות כהוראתו אמנם אם היה המחלוקת בממון או בדבר מביא לידי ממון בדרך שימשך בהוראתו שיהיה הממון לזה בדין או הפך הנה זה יביא לדבר שחייבין על זדונו כרת ועל שגגתו חטאת כאלו תאמר שקדש אשה בזה הממון ולדברי האומר שהוא כדין הרי היא מקודשת ואם קדשה שני אינה מקודשת לשני וזה המחלוקת יביא לחטא במה שחייבים על זדונו כרת ועל שגגתו חטאת והוא איסור אשת איש ואולם המחלוקת בין דם לדם בין נגע לנגע יביא תכף למה שחייבים על זדונו כרת ועל שגגתו חטאת כי לדברי האומר טהור יכנס במקדש ואם היה טמא הרי הוא חייב על זדונו כרת ועל שגגתו חטאת ולפי שמצאנו זה העונש החמור בזקן ממרא לפי שלא נמשך להוראת בין דין הגדול והיה מבואר שזה הדין הוא יותר ראוי בו מבאיש אחר מפני מעלתו ולפי שכבר יתכן שימשך מזה מההפסד יותר ממה שיקרה באחר לפי שהוא יורה לעשות לרבים ויחטיא בזה רבים אמנם איש אחד לא יחטיא בזה זולתו ולזה הוא מבואר שאיש אחד שעבר על הוראת בית דין הגדול אינו חייב מיתה אך הוא עובר בלא תעשה שנאמר לא תסור וגומ' ובטל מצות עשה שנאמר על פי התור וגו' ולזה רצה שכל ישראל ישמעו וייראו כדי שלא יעברו על הוראת בית דין הגדול:
@19 **כי תבא אל הארץ.** הנה הודיעה התורה העתיד להיות לישראל והוא שאחר ירושה וישיבה ישתדלו להשים עליהם מלך ככל הגוים וגו' שמלכם שופט אותם ולזה סמך משה זאת הפרשה לפרשת סנהדרי גדולה וכן היה העניין שהרי אמרו ישראל לשמואל שימה לנו מלך לשפטנו ככל הגוים. והיינו גם אנחנו וגו'. והוא מבואר שמזה העניין ימשך הפסד התורה בכללה כי התורה התחכמה אל שיהיו שם תמיד ראויי' להוראה לבאר משפטי התורה וחקיה ומצותיה בכללם והם יעמידו התורה וישמרוה מהפסד אך כשיהיה זה הענין מסור למלך לא ישאר שם מי שיעמיד התורה ולזה השגיחה התורה בזה האופן שהשגיחה בזקן ממרה והשתדלה שעם היות להם מלך ימשכו לדברי התור' לא לזולתם כמו שיתבאר מדברינו בבאור זאת הפרשה:
@20 **שום תשים עליך מלך.** היא מצות עשה עם התנאים שזכר אחר זה והוא שיהיה זה המלך אשר יבחר ה' בו ר"ל ע"י נביאו כמו העניין בשאול שבחרו ה' יתע' ע"י שמואל כדי שמה שיבחרהו ראוי להתנהג לפי התורה:
@20 **מקרב אחיך תשים עליך מלך.** ר"ל כשהיה שלא יהיה שם נביא ותבחר אתה המלך שימלוך עליך הנה תחוייב למנותו מקרב אחיך כדי שיתנהג בדרכי התור' אשר גדל בה ומנוי המלך יהיה על ידי ב"ד הגדול כי להם הדברים הכוללים לכל ישראל והנה אמר מלך ולא מלכה כי הנשים דעתן קלה ואל תאוה להם המלוכה:
@20 **לא תוכל לתת עליך איש נכרי וגו'.** הזהיר מנתינת איש נכרי על ישר' שלא ידיחם ויביאם לעבור על דברי תורה ואף על פי שהיה גר ממשפחת גרים אלא אם היתה אמו מישראל שאפילו נתעברה מגוי הרי הבן הוא אחינו רוצה לומר שהוא ישראל כמו שבארנו במה שקדם:
@21 **רק לא ירבה לו סוסים.** רוצה לומר יותר מהצורך למרכבתו:
@21 **ולא ישיב את העם מצרימה וגו'.** רוצה לומר שבה יהיה נשמר שלא ישיב העם מצרימה כי אם הותר לו להרבות סוס ישלח לו אנשים לקנותם משם כי שם נמצאים מאד כאמרו ותעל ותצא מרכבה ממצרים בשש מאות כסף וסוס בחמשים ומאה. והנה אם יעברו האנשים האלה למצרים יעברו על מצות השם יתברך כי הוא צוה לישראל שלא יוסיפו לשוב בדרך הזה עוד רוצה לומר בזה יהיה נשמר שלא ישיב העם מצרימה כדי שלא ילמדו ממנהגיהם המגונים מאד כמו שנזכר בפרשת קדושים תהיו:
@22 **ולא ירבה לו נשים ולא יסור לבבו.** מגיד שאם ירבה לו נשים יסור לבבו מהשם יתעלה ומתורתו לרוב נטות מחשבתו על הנשים מצד רבויים הלא תראה כי שלמה שלא קם כמהו במלכים ושרתה עליו רוח הקודש הטו נשים לבבו והנה המספר המותר למלך לקחת מהנשים ואינו רבוי ביחס אל המלך י"ח שהרי מצאנו בדוד שהיו לו שש נשים ואמר לו השם יתעלה ואם מעט ואוסיפה לך כהנה וכהנה ולא התיר לעצמו לקחת יותר ממה ששלח לו הש"י עם הפלגשי' ושלקח ולזה כאשר הוצרך אל אבישג השונמית לחממו לא לקחה לאשה ולא ידעה ולזה היה שואל אותה אדוניה בן חגית להיות לו לאשה כי לא לקחה דוד לו לאשה:
@22 **וכסף וזהב לא ירבה לו מאוד.** רוצה לומר להשימו בבית גנזיו לאצרו לו לעצמו והסבה בזה כי בקשתו רבוי הכסף והזהב יביאהו לקחת אותו שלא כדין ויסור מהתורה ויביאהו אל הגאוה שהיא גם כן סבה לסור מדברי התורה ואולם אם ירבהו לא לו אך לשם יתעל כמו שעשה דוד באוצר הרב ההוא אשר הכין לה' לבנו' בית המקדש או עש זה לצרכי הציבור ומלחמותיהם אין בזה חטא לו:
@23 **והיה בשבתו על כסא ממלכתו וכתב לו את משנה וגומ'.** הנה נתחייב בזה המלך יותר על הספר שיחוייב כל איש לכתוב לעצמו כמו שיתבאר בג"ה והנה נצטוה המלך בזה כדי שישקוד על התורה ותהיה כל הנהגתו על פי התורה ואמו על ספר הוא המגלה לפי הוראת הגדר:
@23 **מלפני הכהנים הלוי'.** אחשוב שאמ' זה להעתיקו מהספר שאצל הכנים הלוים שהוא היותר מדוקדק שאפשר:
@24 **והיתה עמו.** ר"ל התורה תהיה עמו תמיד שהוא פנוי שיוכל להתעסק בה וקרא בו כל ימי חייו ר"ל בספר ההוא יקרא תמיד ואף על פי שקרא התורה פעמים רבות לא יפטר מה כי הכונה הוא לדבקו בדברי התורה בתכלית מה שאפשר כדי שילמד ליראה את השם יתעלה וישמור את כל דברי התורה והחקי' אשר בה לעשותם:
@25 **לבלתי רום לבבו מאחיו.** מגיד שהגאוה מסירה המלכות ממנו ולזה השתדל הש"י להסיר הגאוה ממנו במה שצוהו לשקוד על דברי התורה ושלא ירבה לו כסף וזהב מאד ובזה גם כן ישמור שלא יסור ממצות התורה ימין ושמאל כדי שיאריך ימים על ממלכתו הוא ובניו בקרב ישראל וזה כי בשכר קיומו התורה יתמיד המלכות לו ולזרעו זמן ארוך ואמר הוא ובניו להגיד שהמלך כשזכה במלכות זכה בו לו ולבניו אם לא יגדו' החטא שיסיר הש"י המלכו' מהם וראוי שתדע שמאמרו שום תשים עליך יתבאר הוא ראוי שיהיה באופן שיהיה עליך מלך ר"ל שתשים בלבך שהוא מלך עליך ולזה ראוי שתירא ממנו ולא תעשה דבר שתסור אימתו מעלך ולא יעשה הוא זה גם כן כי ענין המלך לפי מה שיורה עליו הגדר הוא זה וראוי גם כן שיהיה ענינו ותואו בצד שלא יעשוק ממנו האימה על האנשים והוא מכו' שכל האמור בפר' מלך בספר שמואל מלך מותר לו ולזה הסכמנו לזכרו פה כדי שיהיו דיני מלך נכללי' בזה המקום והנה מה שנזכר שם הוא שיש לו רשות לקחת מבני ישר' מעשר מהבהמות והזרעי' והפרות שנא' צאנכם יעשור ויש לו רשות לקחת בעל כרחם עבדיה' ושפחותיהם וחמוריהם לעשות מלאכתו שנאמר ועשה למלאכתו ויקח בני ישראל לחרוש חרישו ולקצור קצירו ולעשו' כלי מלחמתו וכלי רכבו ובנותיה' יקח לרקחות ולטבחו' ולאופות ובניה' לשי' במרכבתו ולהיות פרשיו ולהיות רצים לפני מרכבתו ובחוריהם היפים יש לו לקחת לשמש לפניו ויש לו להטיל על העם מס או מכס שנאמר ואתם תהיו לו לעבדים ועניין העבדו' הוא נתינת המס שנא' יהיו לך למס ועבדוך:
@26 **לא יהיה לכהנים הלוי' חלק ונחלה עם ישר'.** ר"ל לא יטלו חלק בבזה ונחלה עם ישראל ולא נחלה בארץ והנה יש להם תמורת זה אשי ה' והנה הקרבנות שזכו בהם הכהנים ונחלתו הוא מעשר ראשון הוא ללוים כי הוא להם כמו הנחלה ושאר המתנות שהם לכהנים שהם כמו נחלה כמו שהתבאר בפרשת קרח:
@27 **ונחלה לא יהיה לו בקרב אחיו.** רוצה לומר בארץ לפי שהשם יתעלה הוא נחלתו ודי לו נחלתו בזה והרצון בזה כי מפני שאינו כהן שנאמ' חלק כחלק יאכלו ואין שום חלק ללוי בקדשים שיהיו נאכלים בית הבחירה לבד ולזה הוא מבואר שזה הלוי הוא כהן והנה אמר בו ושרת בשם השם אלהיו כמו שאמר קודם זה לעמוד לשרת לפני ה'. למדנו שהוא מדבר בזה המקום משרות הכהנים ולפי שאמר וכי יבא הלוי יעיר על העת אשר ראוי לבא בו הלוי לפי מה שנתבאר מהשרשים הכוללים וזה אמנם הוא ברגלים למדנו כשיבא שם הכהן ברגל הנה הוא רשאי בכל אות נפשו לבא לבית הבחירה ולשרת שם בשם ה' ככל אחיו הכהנים הלוים העומדים שם לפני ה' ולאכל חלק כחלק עמהם מהקרבנות והמנחה:
@33 **לבד ממכריו על האבות.** ידוע שהאבות חלקו הכהנים למשמרות כדי שיהיה איש על עבודתו באופן שלא יהיה שם מחלוקת ולא תתבלבל מפני זאת העבודה הנכבדת וזהו עניין ממכריהם כאלו מכרו זה לזה חלקם בדרך שיטול זה חלקו בשבת זו וזה חלקו בשבת אחרת וזה יעבוד בשבת זו וזה בשבת אחרת ואמר בזה המקום כי מלבד הקרבנות והעבודות שהם מהממכר הזה יכלו לעבוד הכנים בשוה ולחלק ביניהם חלק כחלק והם הקרבנות והמנחות שהם מפני הרגל ואולם הקרבנות שאינם מפני הרגל המיוחסים לשבת ההוא יהיו לאנשי המשמר לבד העבודה והאכילה לא לזולתם מהכהני' ולפי שהוצרכה התורה להתיר זה לכהנים בעלותם לרגל למדנו שכונת התורה הוא שיהיו הכהנים משמרות כי בזולת זה לא תשלם זאת העבודה הנכבדת באופן ראוי והנה אמרו וכי יבא הלוי יכלול גם כן באו שם להביא קרבנותיו או נדריו ונדבותיו כי מן הראוי לבא שם ולזה יוכל לעבוד אז באלו הקרבנות ולאכל עמם חלק כחלק ואחשוב שכבר אמר כי יבא הלוי לכלול בזה העניין הלוי שהוא גם כן נחלק למשמרות והנה לעניין השרות שהוא בשם יתעלה והוא השיר שאומרי' הלוים על הקרבנות יהיה הבא מהלוי' יכול לשרת בכל אות נפשו לא בשאר עבודות הלוים כי הם לאנשי המשמר. והנה למדנו מזה המקום שהלוים גם כן יחוייב שיהיו נחלקים למשמרות בדרך שיהיה איש על עבודתו ועל משאו כמו שזכרה התורה בפרשת במדבר ופרשת נשא הנה זה ביאור מה שיצטרך אל ביאור מזאת הפרשה שהגבלנו ביאורה פה.
@34 **לא תלמד לעשות כתועבות הגוים ההם.** ידוע שאין הכונה בזה שלא תהיה האזהרה הזאת רק בארץ וזה שאין בכאן דבר יהיה לו התלות בארץ בצד מהצדדים וכבר הזהיר על קצתם גם כן במקומות אחרים ולא התנה בהם שיהיה זה בארץ ואמנם הכונה בזה הוא כי כבר הוצרך הזהירם על זה יותר מפני באם אל הארץ שימצאו שם הגוים ההם עושים אלו הפעולות המגונות ולזה אמר שלא ילמדו לעשות כתועבות הגוים ההם וזהו מצות לא תעשה ולמדנו מזה שלא הזהיר אלא שלא ילמדו לעשות כתועבות הגוים ההם וזהו מצות לא תעשה ולמדנו מזה שלא הזהיר אלא שלא ילמדו לעשות אבל יוכלו ללמוד להכין ולהורות והנה יחוייב לסנהדרין שידעו אלו הדברים מה הם ואיך הם כדי שיוכלו לשפוט עליהם כפי הראוי:
@35 **לא ימצא בך מעביר בנו ובתו באש.** והיא העברה למולך וענינה היה שיעביר האדם קצת זרעו בין האש וידמה אז שכבר כרת ברית עם אלוה ההוא כמו שביארנו באמרו ומזרעך לא תתן להעביר למולך:
@35 **קוסם קסמים.** הוא העושה קצת פעולות כדי שתתבודד מחשבתו ויגיד העתידות מפאת הקסם ובו מינים רבים קצתם יותר מגונים מקצת שכלם בלא תעשה והנה הזהירה התורה מה מפני מה שימשך מזה מההפסד למה שימצא מהכזב בזה המין מההודעה עם שיש בו מינים יתקרבו מאד לעניין עבודה זרה והוא שיעשו מונות ויקריבו לפניהם קצת קטורים וידמו שהצורה תדבר או להם ולזה אחשוב שסמכו למעביר בנו ובתו באש:
@35 **מעונן.** אחשוב שמעונן הוא שיאמר שעה פלוני טובה לכך או רעה ויהיה זה המאמר מופשט מכל סבה אחרת מחייבת זה אך אם יאמר שבתשרי או במרחשון ראוי לזרוע זרעים כך כאמרו תן חלק לשבעה וגם לשמנה ובאדר זרעים כך מפני טבע ההויות מהם או שיאמ' שאין ראוי להקיז דם בתקופת תמוז מפני תגבורת תחום אז או שאין ראוי לחתוך אילן אחר חדוש הירח מפני יתרון הלחות בו או שיפסידהו ויעפשהו וכיוצא בו אינו מכלל העוננות:
@35 **ומנחש.** הנה בענין הנחוש הוא שינחש האדם ויאמר אבא במקום כך ואם יקרה לי כך אעשה כך ואם לא לא כמו שעשה אליעזר ויהונתן או יהיה שילך במקום מה וימצא בדרכו שועל וישוב לו מפני זה להיותו מנחש שכבר ידומה בפעולתיו שיהיה משתדל בעשייתם ואולם בדברים שעברו אינו נחש שיהיה אסור כמו שאמ' נחשתי ויברכני ה' בגללך ולזה רצה שישב עוד אצלו וכן הענין במה שידמה לזה:
@35 **ומכשף.** הוא העושה מעשה כשוף לא האוחז את העינים ויביא לדמות שהוא עושה ואינו עושה וכבר נתבאר זה במה שקדם:
@36 **וחובר חבר.** הוא האומר קצת דברים יחשוב שבאו אז נחשים ועקרבים או אי זה מין שירצה או יאמר לחש על נשיכת עקרב או נחש ויחשוב שיסור חיזקם:
@36 **ושואל אוב.** הוא השואל דבר מבעל אוב והנה בעל אוב בסקילה והשואל לו הוא בלא תעשה ודבר האוב הוא שיעשה בעל האוב קצת פעולות ויאמר קצת דברים עד שידמה השואל שהמת מדבר עמו מתחת הארץ בקול נמוך מאד בלתי נשמע כי אם לשואל כאמרו ושפל מאוב קולך:
@36 **וידעוני.** הוא הדורש אל בעל הידעוני הוא שמניח עצם עוף ששמו ידוע בפיו ויפול כמו נכפה ודיבר בפיו לפי מחשבתו דברים שעתידים להיות:
@36 **ודורש אל המתים.** הוא באי זה צד שיהיה ודורש אליהם אם שילין בבית הקברות ויתבודד דמיונו בעניין המתים וישוב שהמת ידבר עמו ויודיעהו דברים העתידים או יהיה נשאל בגולגלת המת ויעשה פעולות וידבר דברים עד שידמה שיהיה קול נמוך יוצא מתחת שהיו וידבר לו דברים העתידים. והנה אלו הדברים כלם הם רבי ההפסד והגנות והם תועבה השם יתעלה ובגלל התועבות האלה מוריש השם ית' הגוים האלה מפניך:
@38 **תמים תהיה עם ה' אלהיך.** צוה שיהיה בשלמות עם השם יתע' שלא יהיה לבו נקפו כלל באלו השגעונות ולא יפותה אליהם:
@39 **כי הגוים האלה אשר אתה יורש אותם אל מעוננים ואל קוסמים ישמעו.** רוצה לומר כי מפני היותם תחת המזל יקרה להם שיגידו קצת עתידות בזה האופן אך אתה אינך כן כי הנביא לבד הוא אשר יגיד לכם המתחדש באמרו כי לא נחש ביעקב ולא קסם בישראל בעת יאמר ליעקב כמו שפירשנו בפרשת בלק או ירצה כי אלו הגוים לחסרונם לא השגיח השם יתעלה בהם להודיע להם העתידות ואין להם מפני זה נביא ולזאת הסבה נתפייסו באלו המהתלות שיודיעו המעוננים והקוסמים ואולם אתה הנה נתן לך ה' אלהיך שהגיע לך הודעת עתידות בשלמות על יחדי הנביא:
@40 **נביא מקרבך מאחיך כמני וגומ'.** רוצה לומר שאני מקרבך מאחיך אך אין הרצון בזה שיהיה במדרגת משה שהרי זכרה התורה שלא קם נביא עוד בישראל כמשה ולזה אמר אחר זה ונתתי דברי בפיו ולא אמר ואודיעני פנים אל פנים:
@40 **יקים לך ה' אלהיך.** ולזה לא תצטרך לטרוח ללכת בארץ אחרת לדעת העתידות:
@40 **אליו תשמעון.** רוצה לומ' בכל מה שיצוה אתכם מעניני הרשות כמו שמואל לשאול שבעת ימים תוחיל עד בואי אליך ולא קיים מצותו ואמר לו שמואל שכבר עבר על דברי השם יתעלה וכבר רבו המשלים בזה בדברי הנביאים והוא מבואר ממה שבא אחר זה שאפילו במצות התוריות צוה לשמוע אליו וראוי שנחקור מזה ונאמר שאם היתה הכונה בזה שיזהיר לשמוע כל דברי התורה הנה לא יהיה זה הענין שמיעה אליו אבל שמיעה לדברי התורה ואם היתה מצותו לסור ממצות אחרות מהתורה הרי נתבאר במה שעבר שאם צוה לעבוד עבודה זרה לא תשמע לו אפי' לפי שעה ואם היתה מצותו לסור ממצות אחרות מהתורה תמיד הנה זה יהיה גדעון מהתורה והתורה אמרה לא תגרע ממנו וכן הענין בהוספתה כי על דרך הנבואה לא תתכן התוספת בתורה מצוה לדורות ולזה ידמה שסמך בפרשת ראה אנכי אל אמרו לא תוסף עליו ולא תגרע ממנו פרש' נביא השקר להורות שלא נקבל על דרך נבואה שום הוספה תמידית ושום גרעון תמידי בדברי התורה ולזה יחוייב שנשמע אליו במה שצוה לסור ממצות אחרות ממצות התורה שלא תתלה בענין האלהות לפי שעה כמו שמצאנו באליהו בהר הכרמל ובגדעון בן יואש לפי מה שפירשנו בספר שופטים:
@41 **ככל אשר שאלת וגומ'.** רוצה לומר כמו ששאלת בחורב שלא תשמע התורה מפי השם יתעלה אך מנביאו כי יראת מהאש הגדולה ולזה אמרת אלי שאדבר עמכם ותשמעו ולא ידבר עמכם אלהים ויטב בעיני השם יתעלה ונתן לכם תורתו בשלמות על ידי. רוצה לומ' מה שינהג ממנה תמיד ולפי שבקצת העתים יצטרך לי שעה לעבור על קצת המצות שהוא יותר טוב אז לסבה מה כמו שספרנו מעניין אליהו בהר הכרמל הנה ישמעו זה מפי נביא גם כן שכיון שברחו מלשמוע אלו הדברים מפי וזה שכבר אקים להם נביא מקרב אחיכם כמוך שאתה מקרב אחיהם יהיה אצלם:
@43 **ודבר אליהם את כל אשר אצונו.** הן מדברי תורה הן מדברי רשות:
@44 **והיה האיש אשר לא ישמע אל דברי אשר ידבר בשמי אנכי אדרוש מעמו.** רוצה לומר שיהיה חייב מיתה בידי שמים ואמר זה כי אולי יהרהר אחר הנביא ויאמר איך אעבור על דברי התורה. ואולם זאת המחשבה ממנו היא נפסדת כי הוא אינו עובר על דברי התורה אם ישמע אל דבריו לעבור על קצת דברי התורה לפי שעה אך יעבור על דברי התורה אם לא ישמע אל דבריו כשלא היתה מצותו לעבוד עבודה זרה או כנגד אמונת השם יתעלה והיה נכלל בזאת האזהרה נביא שעבר על דברי עצמו:
@45 **אך הנביא אשר יזיד לדבר דבר בשמי.** מגיד שאם לא עשה זה בזדון אינו חייב מיתה:
@45 **אשר לא צויתיו לדבר.** אבל הוא בודה מלבו אלו הדברים ואומר אותם בשמי ויתחייב זה מיתה מפני שנתנבא בשקר ואמר דברים יביאו להכחיש הנבואה או שיביאו לעבור על קצת דברי התורה אשר אנחנו מחוייבים לשמוע לדברי הנביא כהם והמשל שיאמר בשם השם יתעלה שהמטה אשר בידו יהפך לנחש ביום פלוני או יוציא פרח ויוצץ ציץ ויגמול שקדים ביום פלוני וכשלא יקרה זה יתחדש מזה מההפסד שיאמין קצת המון העם שאין יכולת בהשם יתעלה לעשות אלו הנפלאות או שיאמר שהשם יתעלה צוה שילחמו עם זה פלוני ביום השבת והוא לא צוה על זה ויהיה סבה אל שיעברו בזה על מצות התורה והנה יכלול אמרו אשר לא צויתיו לדבר שיאמר השם יתעלה שלחו לומר דברים שמה שצוה אותם השם יתעלה לנביא אחר והנה הפסד שיקרה מזה הוא כי אחר זה יאמר דברים אחרים בשם יתעלה ויחשבוהו העם כנביא ויהיה זה העניין מן ההפסד מה שכבר זכרנו ובכלל אשר לא ציותים לדבר הוא שיאמר דבר בש' השם יתעלה אשר יתבאר לך מהעצם מאמרו שיי' לא צוהו על זה כמו שיוסיף לדורות מצוה או יגרע כי כבר הודיעתנו התורה שזה לא יהיה ונתבאר עוד זה מצד העיון כי לא יתכן שיוחס אל השם יתעלה זה העניין משנוי הרצון:
@45 **ואשר ידבר בשם אלהים אחרים.** רוצה לומר מיתת חנק:
@46 **וכי תאמר בלבבך איכה נדע את הדבר אשר לא דברו יי'.** לפי שצוהב כאן שהמתנבא בשם יי' מה שלא צוהו לדבר הוא חייב מיתה הנה צריך לבית דין שתהיה להם חינת ידעו בה הדבר אשר לא דברו יי':
@47 **אשר ידבר הנביא בשם השם יתעלה ולא יהיה הדבר ולא יבא.** הנה זהו לפי מה שאחשוב אם בעצם הדבור שאמר בשם השם יתעלה. אם באות שישאלו לו אחר זה אמנם בעצם הדבר כמו שיאמ' שכבר מת איש ככה ויחקרו עליו אחר כן ומצאנו שאין הענין כן או שהשם יתעלה אמר אליו שביום ככה יהפכו מי הבור פלוני לדם ובא הזמן ההוא ולא בא מה שייעד ואפשר עוד שיהיה בעצם הדבור באות שיתן עמו באמרו להם המאמר כמו שיאמר שצוהו השם יתעלה שיאמר להם שילכו בעת מה במקום פלוני ואמר עם זה וזה לכם האות שבמקו' ככה תמצאו עתה דבר כך ולא היה כן או שיאמר להם כי ביום פלוני יתחדש אות מה ולא נתחדש וכבר יהיה זה בעצם הדבור באופן אחר כשיאמר להם בשם השם דבר ידוע להם שלא יהיה ולא יבא לעולם ממנו זה הדבר לעולם כמו שיאמר להם בשמו להוסיף לדורות מצוה או לגרוע אותה לדורות ואמנם מה שיהיה מפני אות ישאלו ממנו אחר זה ולא יהיה ולא יבא הנה הוא מעיד שהוא אינו נביא ולזה יתבאר שהדבר שדברו הנביא בשם השם לא דברו יי' וראוי שנחקור בכאן מספק עצום יקרה בזה וזה שלא יתאמת אף על פי שלא יהיה הדבר ולא יבוא היות זה המידע בו נביא שקר וזה שאם היה בזה הייעוד רע הנה השם יתעלה חנון ונחם על הרעה כמו שנתבאר מדברי ירמיהו אל חנניה בן עזור ואם היה הייעוד טוב גם שם לא יבחן אם לא יבוא שהוא נביא שקר כי אולי יעד השם יתעלה הטוב ההוא מפני טוב דרכיהם וכאשר סרו מדרכם הטובה ינחם השם יתעלה מהטוב אשר דבר להביא להם כמו שאמר ירמיהו רגע אדבר על גוי ועל הממלכה והנה התבאר מזה שגם הייעוד הטוב חוזר והיות הענין כן הנה יפול ספק במה מהיעודים יבחן הנביא ונאמר כי לא יבחן הנביא בשם יעוד שיהיה בו תנאי או שיהיה בכחו תנאי רוצה לומר שמעצם היעוד תחייב תנאי כמו הענין ביעוד הטוב שלא יקח זמן מוגבל ומקום מוגבל כמו שביארנו בפרשת וישלח יעקב או כמו הענין ביעוד הרע כי יש תנאי בכחו איך שיהיה כמו שביארנו שם ואולם בייעוד הטוב שיהיה מפני דבר יש תנאי ויסור בסורו וכשלא היה ענינו כן הנה יכהן הנביא שאם יאמר בו שקר הנה הוא נביא שקר והנה יבחן הנביא בכל מה שיאמר מהדברים שהם כך בעת ההוא היה טוב או רע שאם לא נמצאו כן נודע באמת שהוא נביא שקר וזהו אמרו ולא יהיה הדבר ויבחן הנביא עוד במה שיודיע מהדברים העתידים שאין בהם טוב ורע לאיש או לאנשים היה שיאמר שיתחדשו על דרך המופת או שלא יהיה בחדושם דבר זר אצל הטבע כי כשיתבאר שלא יבוא מה שיעד בו הנה נתבאר שהוא נביא שקר:
@47 **בזדון דברו הנביא לא תגורו ממנו.** רוצה לומר כיון שדברו הנביא בזדון. לא תגורו ממנו רוצה לומר אל תיראו מלהמיתו מפני היותו גדול המעלה אצלך ולזה הוא מבואר שאין ראוי לשתוק מללמד עליו חובה ולפי שזה הענין הוא דבר גדול כי הנביא הוא על כל ישראל אם היה נביא אמת הנה לא ישפטוהו כי אם בית דין הגדול שבמקום הבחירה וראוי שלא יעלם מממנו כי בית דין הגדול יש להם כח לעבור על מצות התורה להוראת שעה ולגדר ולסייג שהרי אנחנו מחוייבים לעשות על פי התורה אשר יורו והוא שיהיה להוראת שעה:
@48 **כי יכרית ה' אלהיך את הגויים.** מגיד שאחר ירושה וישיבה בערים ובבתים רוצה לורמ שתשלם החלוקה לשבטים וכל בני השבט קצתם עם קצת חוייבו להבדיל אלו השלש ערי מקלט לא קודם זה וכן מצאנו שהיה הענין בספר יהושע:
@49 **שלש ערים תבדיל לך בתוך ארצך.** אמר זה לפי שלא היה ראוי שתהיינה קצתם בקצות הארץ אבל היה ראוי בזה שישלשו גבול הארץ בדרך שיחלקוהו לשלשה חלקים ובאמצע כל חלק מאלו החלקים תהיה עיר מקלט והנה העדים צריך שיהיו בינונייות לא גדולות ולא קטנות:
@50 **תכין לך הדרך.** הנה הכנת הדרך היתה כדי שיוכל לכוין הרוצח עיר מלקט לנוס אליו וזה היה כתוב מקלט בדרך אשר תביאהו אליו והיתה עוד הכנת הדרך שלא יהיה שם אבן נגף וצור מכשול ולא תל ולא נהר ואם היה שם היו עושים גשר עליו כדי שלא יכשל שם הרוצח ולא יצטרך להתעכב לעבור הנהר והיה עוד מהכנת הדרך שיהיה רחב כדי שלא יכשל שם:
@50 **והיה לנוס שמה כל רוצח.** רוצה לומר היה שהרג שוגג או מזיד הנה ינום שם עד שיתברר דינו ואם היה למות ישלחו זקני עירו ולקחוהו משם ויתנוהו ביד גואל הדם להמיתו כמו שאמר אחר זה בסוף זאת הפרשה:
@51 **וזה דבר הרוצח אשר ינוס שמה וחי.** רוצה לומר שבאלו התנאים תהיה העיר קולטת אותם באופן שלא ימות ביד גואל הדם:
@51 **אשר יכה את רעהו בבלי דעת והוא לא שונא לו מתמול שלשום.** מאמרו אשר יכה את רעהו למדנו שישראל גולה אם הרג ישראל בשגגה וגר תושב אם הרג ישראל בשגגה וגר תושב אם הרג גר תושב בשגגה גולה שהרי אמר בפרשת אלה מסעי שערי מקלט הם לישראל ולגר תושב בתוכם. והנה השננא אף על פי שיעשה בבלי דעת לא יחשב כשוגג כמו שביארנו בפרשת אלה מסעי ואינו גולה:
@52 **ואשר יבא את רעהו ביער לחטוב עצים וגומ'.** למדנו מזה שאם היה העניין ביותר מהשגגה הזאת או פחות אינו גולה משל מה שהוא ביותר שהיה סותר את כותלו ברשות הרבים ונפלה אבן על אדם ומת בבלי דעת והנה זה הוא כמו פושע ואינו גולה משל מה שהיא בפחות שסתר את כותלו בלילה במקום שאין דרך אדם לבוא שם כי זה כמו אנוס או שיהיה כמו בוקע עצים במקום שאין אדם רגיל לבוא שם:
@52 **ונשל הברזל מן העץ והכה את רעהו ומת.** ולא ידע שישנו שם או שיהיה בוקע עצים ונשבר קצת הברזל מן הגרזל והמית כי אין זה מצוי כמו הסרת הברזל מן העץ וכן אם נשל הברזל מן העץ והכה באבן והפילה על ראש אדם ומת אינו גולה כי הוא כח כחו והתורה לא חייבה גלות אלא כשהיה כחו ולמדנו מאמרו ביער שאם היה הרוצח בוקע עצים ברשותו ונשל הברזל מן העץ ומת ברשות המזיק שאין הרוצח גולה כי אינו ביער שיש רשות לנרצח לבא שם. ולמדנו מאמרו ומצא את רעהו ומת שאם המציא רעהו עצמו כשנשל הברזל מן העץ בדרך שהכהו או כשהשליך האבן הרוצח באבן בלא ראות אינו גולה שנאמר ומצא את רעהו לא שימציא הוא את עצמו ואמר בפרשת ואלה מסעי ויפול עליו ולא שיפילה הנרצח על עצמו ולמדנו מזה גם כן שראוי שיהיה זה בדרך מציאה או בדרך נפילה ולזה אם נפלה האבן בעת ההוא מכון להעלותה כאלו תאמר שהיה מושך אותה בחבל להעלותה ונפסק החבל ונפלה הנה אין זאת נפילה או שנשל הברזל מן העץ בעת שהוא מגביה אותו לאחוריו כמנהג הכורת העץ אין זו דרך מציאה ועוד שהתורה אמרה ונדחה ידו בגרזן לכרות העץ בעת שהוא מניע הגזרן לכרות לא כעת שהוא מניעה להגביה ולזה יהיה כאלו פטור מלגלות וכן אם בא הרוצח ברשות להכות הנרצח והרגו בשגגה בעת עשותו המצוה אינו גולה כמו האב המיסר את בנו והרב תלמידו והנה למדנו זה מאמרו לחטוב עצים שהוא דבר הרשות וראוי שתדע שאם לא מת הנרצח תכף באופן שיהיה שם דרך לומר שלא מת מחמת המכה אינו גולה שם שנאמר ומצא את רעהו ומת שימות מהמכה לא מפני דבר אחר:
@53 **פן ירדוף גואל הדם אחרי הרוצח.** מגיד שקודם שהתבאר שהוא גולה ראוי לשמור שלא ירדוף גואל הדם את הרוצח וישיגנו ולזה צותה התורה שנבדיל עוד שלש עדים כדי שלא ירבה הדרך ויהיה זה סבה שישיגנו ואמנם אח' שהתבאר שהוא גולה ישתדלו יותר בשמירתו שהרי אמר בפרשת אלה מסעי והשיבו אותו העדה אל גבול מקלטו ולזה צריך שיתנו לו חבורה שישמרוהו בדרך מגואל הדם בדרך שיושיבוהו אל מקלטו אשר נס שמה. וראוי שתדע שמי שאינו גולה מפני שלא הגיע עניינו לשגגת הגולה. הנה אם הרגו גואל הדם נהרג עליו אולם מי שאינו גלוי מי שחטאו יותר גדול מחטא הגולה הנה אם הרגו גואל הדם פטור כמו הענין במחוייב גלות שאם הרגו גואל הדם חוץ לעיר מקלטו פטור והנה נבאר בכאן מה שנתחדש מביאור זה הדין בספר יהושע וזה שכבר נאמר שם שהרוצח יעמוד פתח שער עיר המקלט וידבר את דבריו באזני זקני העיר ההיא רוצה לומר שיאמר להם שהוא רוצח והם יתנו לו מקום וישב עמם למדנו מזה שבערי המקלט יחוייב להם לתת מקום לרוצח בזולת שכירות לא בשאר ערי הלוים אף על פי שכלם קולטים כמו שזכרנו במה שקדם ולזה אם ירצה לשבת שם יחוייב לתת לו מקום בלא שכירות. ואמר שם וישב בעיר היא עד עמדו לפני העדה למשפט עד מות הכהן הגדול מגיד שבעיר מקלטו שנס שמה ראשונה שמה הוא שב בהתברר הדין שהוא גולה עד מות הכהן הגדול:
@55 **וירחיב ה' אלהיך את גבולך ונתן לך את כל הארץ אשר דבר לתת לאבותיך.** הוא ארץ הקני והקניזי והקדמוני שלא נתנו לישראל עד הנה ויעד השם יתעלה נתינתם לאברהם:
@56 **כי תשמור את כל המצוה הזאת וגומ'.** מגיד שאם היו ישראל שומרים כל מצוות התורה היו נגאלין:
@56 **ויספת לך עוד שלש ערים על השלש האלה.** זה לאות שזה דבר עתיד כי לא מצאנו שהוסיפו ישראל על שש ערי מקלט ועוד שהרי אמר השם יתעלה בתתו עשרת השבטים ביד ירבעם אענה את זרע דוד אך לא כל הימים מגיד שעתיד המלכות להיות כלו לזרע דוד וזה דבר לא נהיה עד הנה ולזה הוא דבר עתיד בהכרח אשרי המחכה ויגיע:
@57 **ולא ישפך דם נקי בקרב ארצך.** ויהיה עליך חטא עצום אם ישפך דם נקי בקרב ארצך:
@58 **וכי יהיה איש שונא לרעהו.** אמר זה לפי שלא יכוין אחד להרוג אחר אם לא היה שונא לו וארב לו. למדנו מזה שהמכוין להרוג את זה והרג זה אינו נהרג שהרי לא ארב לו:
@58 **והכהו נפש ומת.** לא מי שאפשר לומר שמת מחמת דבר אחר:
@58 **ונס אל אחת הערים האל.** להמלט מיד גואל הדם עד שיתברר דינו למות ואחר שנתברר דינו מות ישלחו זקני עירו ויקחו אותו מעיר מקלטו לגמור הדין בפניו ואחר יתנוהו ביד גואל הדם בדרך שימות בידו:
@60 **לא תחוס עינך עליו.** רוצה לומר על הרוצח. אבל השתדל שימות לפי המשפט:
@60 **ובערת הדם הנקי מישראל.** רוצה לומר שופכי הדם הנקי:
@61 **לא תשיג גבול רעך אשר גבלו ראשוני'.** הזהיר בזה מלשנות הגבול בנחלות לפחות קרקע הכירו ואמר אשר גבלו ראשונים להודיע שאם נשתנה הגבול שגבלו ראשונים לאי זו סבה שתהיה והשיגו זה להשיבו למקומו אינו עובר על זה הלאו:
@61 **בנחלתך אשר תנחל.** מגיד שבארץ עובר זה על שני לאוין על לא תגזול ועל לא תשיג אם עשה זה בחזקה ובאונס או על לא תגנוב ולא תשיג אם עשה זה בסתר ובגנבה אמנם אינו עובר כי אם על לאו אחד:
@62 **לא יקום עד אחד באיש לכל עון ולכל חטאת.** למדנו בזה שעד אחד אינו נאמן שישפטו על פיו לכל עון ולכל חטאת איזה חטא שיחטא האדם בו והנה יתבאר מזה שאף על פי שאינו קם לחתוך על פיו המשפט בשלמות הנה הוא קם לחייב שבועת האיש ההוא כמו שמצאנו בסוטה שאף על פי שאין שם עדים שנטמאה לגמור דינה על פיהם הנה יקום בה העדות החלוש ההוא לשבועה:
@62 **על פי שנים עדים או שלשה עדים יקום דבר.** הקיש בזה עדות שלשה לעדות שנים כמו שביארנו במה שקדם על דבר דיני נפשות:
@63 **כי יקום עד אחד באיש לענות בו סרה.** ראוי שתדע שזה העד הוא שנים כי בזולת זה לא יהיה עדות ולא יתכן בו לומר בו כאשר זמם כי עד אחד לא יאמן להביא עליו עונש והנה אלו העדים העידו דבר שהוא סר מדרך האמת:
@64 **ועמדו שני אנשים אשר להם הריב לפני יי'.** מגיד שאלו העדים המעידים שקר יחוייב שיבואו במקום הבחירה לבחון אם הם עדי שקר לפני סנהדרי גדולה ההם הכהנים או השופטים אשר יהיו בימים ההם ודרשו השופטים היטב והנה עד שקר ראוי שישאל שואל איך יבחן שהם עדי שקר כי אף על פי שיעידו מאה כנגד עדותן לא נתברר שעדותן שקר כי השנים נאמנים כמאה כמו שקדם מאמרו על פי שנים או שלשה עדים ואם מפני הדרישה והחקירה איך יתברר שהם עדי שקר מפני שאינם מסכימים זה לזה במקום או בזמן ועוד אם היה שלא יסכימו זה לזה אולי האחד הוא מעיד אמת ומי יודע אי זהו מהם המעיד שקר ואיך יתכן לומר באחד כאשר זמם והנה הדין לא יגמר מפני עדות אחד ולזה יחוייב שנאמר שמצד הדרישה יתבאר ששניהם מעידים שקר והמשל שעם הדרישה החקירה יאמרו שזה היה בירושלם ביום פלוני ויבאו עדים אחרים שיעידו שביום ההוא היו אלו העדים עמהם במקום רחוק מירושלם למרחק עצום שלא יתכן שיהיו ביום ההוא בירושלם כי זה ממה שיחוייב יהיו אלו העדים הראשונים עדי שקר ואפילו היו הראשונים מאה או יותר והשנים שנים לבד ואם יאמר אומר למה יאמינו יותר דברי השני' מדברי הראשוני' שמעידים שכבר היו ביום ההוא בירושלם התשובה הנה הוא יודע שהאדם אינו נאמן בדברי עצמו כדי שיאמן עליו אחד ולזה תמצא שאפי' מאה שיאמרו שאינם חייבין לראובן דבר ובאו שנים עדים והעידו שהם חייבים לו מנה הנה השנים עדים יהיו נאמנים כנגד המאה שהם נוגעים בעדות וכן בזה המקום הוא ידוע שמה שהעידו העדים שראובן הרג שמעון ביום פלוני או במקום פלוני הנה אינם מחייבים אותו מיתה מפני הרגו אותו ביום ההוא או במקו' ההוא כי באי זה יום שהרגהו הוא חייב מיתה ולזה הוא מבואר שאמרם במקום פלוני וביום פלוני אינו מעם העדות אבל הוא לבחון עניינם אם יאמרו אמת אם לאו ולזה הוא מבואר שהם נוגעים בעדותן בזה הענין והשני' שמעידים כנגדם אינם נוגעים בזה העדות כי אינם מעידים בעניין אחר יהיה העונש בעבורו זולתי על עדותן במקום ובזמן ולזה יהיו נאמנים השנים כנגד הראשונים:
@65 **העד שקר ענה באחיו.** מגיד שלא יעשו דבר כנגדו עדיין זולתי שהעיד בו שקר ולזה גם כן אמר כאשר זמם לעשות לאחיו שזמם לבד ולא עשה ואולי יחשוב חושב כי הדברים ק"ו אם מפני העדות שקר לבד יתחייבו בו אף על פי שלא הגיע ממנו התכלית הרע אשר בעבורו העידו לשקר כל שכן שיתחייבו. אם נתנה פרייה ומחשבתם הרעה אלא שכאשר יעויין בזה לטעון בזה טענה לומ' שאין ראוי שיעשו העדי' זוממין אח' שהגיעה המחשבתם לפועל על יד בית דין וזה כי הש' יתעלה מסכים למה שישפטוהו שופטיו ומאתו משפטיו כאמרו ונקי וצדיק אל תהרוג כי לא אצדיק רשע הגיד בזה כי מי שהצדיקוהו היה מהשם יתעלה להצדיקו כמו שביארנו בפרשת ואלה המשפטים ולזה אמר שלמה פלגי מים לב מלך ביד ה' אל כל אשר יחפוץ יטנו ואמר אלי הוא ממלוך אדם חנף ממוקשי עם כי אל אל האמר נשאתי לא אחבול כמו שביארנו לספר איוב והנה היה זה כמו שליח לעשות רצון השם יתעלה באיש ההוא שחטא בדבר אחר ואם לא חטא בזה עם שזה יהיה בושת לבית דין אם יתפרסם שדנו איש להריגה דרך משל על לא חמס בכפיו ויביא זה להרהר אחר משפטי התורה שלא יהיו ישרים ולאלו הסבות יתבאר שאין ראוי שנעניש העדים בזה האופן כאשר יצאה מחשבתם לפועל:
@66 **ועשיתם לו כאשר זמם לעשות לאחיו.** רוצה לומר שאם חשב להפסיד ממון יפסיד ממון להלקותו ילקח להמיתו ימות ואם חשב להזיקו במה שאי אפשר שיוזק בו זה העת כאלו תאמר שהעידו על כהן שהוא בן גרושה או בן חללה או זונה אין העונש להשים אותם חללים כמו שחשבו לעשות לכהן כי זה בלתי אפשר אך היו לוקים בעבור עברם על לא תעשה שהו' לא תענה ברעך עד שקר ולפי שאמ' לאחיו למדנו שזוממי עדות בת כהן שזנתה אינם בשרפה אך בחנק כמו שחשבו לעשות לאחיהם והוא האיש שאמרו ששכב עמה עם שהענין בבת כהן הוא דבר חדוש שהיא בשרפה ובועלה בחנק ולזה לא ימשך זה החדוש כי אם במקום שבארה בו התורה:
@66 **ובערת הרע מקרבך.** בער העושה הרע מקרבך וימשך מזה שיתבער הרע והנשארים ישמעו וייראו ולא יוסיפו לעשות כדבר הרע הזה בקרבך אמר זה בעדים זוממים לפי שכבר יחשב שהם אינם עושים חטא גדול כמו שיחטא ההורג חבירו או המזיק לו והחובל בו בידו ולזה יקלו האנשים בזה החטא ויהיה זה סבה להפסיד הקבוץ המדיני ולזה היה הענין בתכלית הרע וההפסד ולזאת הסבה רצתה התורה שיתפרסם דינו לכל ישר' וזה יהיה בעלותם שם לרגל כדי שיראו כלם מעשות בדבר הרע הזה:
@68 **ולא תחוס עינך נפש בנפש.** הזהיר בזה מלרחם על עד זומם מלעשות לו כאשר זמם נפש בנפש רוצה לומר שאם יחייבו מיתה בעדותן ידונו במיתה ההיא שנאמ' כאשר זמם:
@68 **עין בעין שן בשן יד ביד רגל ברגל.** ראוי שתדע שאי אפשר בעדות שיחייבו בו חסרון אבר כי המחסר אבר יענש בממון כמו שביארנו בפרשת ואלה המשפטים ולזה ירצה בו בזה המקום עונש ממון ולפי שצוה שלא לחמול על עד זומם שלא השלים מחשבתו למדנו שכל שכן שאנחנו מוזהרים מלחמול על החובל בחבירו באיזה צד שיהיה מאותם החמשה דברים שזכרנו ביאורם בפרשה ואלה המשפטים וכבר ביארה זה התורה עוד בביאור בבושת אמר וקצותה את כפה לא תחוס עיניך ואמר עין בעין שן בשן יד ביד רגל ברגל להורות שקנס הממון ישוער לפי האבר שהיה בו הנזק ולמדנו עוד בזה תועלת אחר והוא שכמו שהעין יותר נכבד לאין שיעור יותר מהשן וזה מפורסם מעניינו כן היד היא נכבדת לאין שיעור מהרגל כי היד הוא כלי להשתמש בה בכל המלאכות המעשיות וכמו שהעין יש לו מבוא גדול בעיוניות לראות המוחשים וללמוד ספרים כן הענין ביד כי ביד שיכתוב האדם יתיישר בתכלית מה שאפשר לעמוד על סודות הדברים שתהיה חקירתו בהם והיתה מחכמת המשל הזה כי כמו שהעין הוא למעלה מהשן כן היד למעלה מן הרגל הנה זה ביאור מה שיצטרך אל ביאור במה שהוגבלנו ביאורו מזאת הפרשה.
@69 **כי תצא למלחמה.** הזהיר לירוא מהאויבים ואף על פי שהם עם רב מישראל ויש להם סוס ורכב כי ראוי להם לבטוח בשם יתעלה אשר אין מעצור לו להושיע ברב או במעט ויעיד על זה שכבר העלנו מארץ מצרים בכח גדול וביד חזקה עם היות ישראל אז בתכלית החולשה ולא בחרב ולא בחנית הושיעם השם יתעלה והנה הזהיר מלירוא מהם כי עם שזה הוא ממעוט הבטחון בשם יתעלה הנה הוא דרך אל שינוצחו ישראל:
@70 **והיה בקרבכם אל המלחמה.** הנה יתבאר שזה הדבור יהיה בקרב ישראל אל המלחמה והוא ברצותם לערוך מלחמה כי אז הם בתכלית הקורבה למלחמ' וכבר יתבאר עוד מהדברים הבאים אחר זה:
@70 **ונגש הכהן ודבר אל העם ואמר אליהם.** מגיד שהכהן המיוחד לזה ידבר אז בכללות אל העם אלו הדברים הנזכרים בכאן תחלה ולפי שהם נאמרים להמון רב הנה יחוייב שיהיה זה המאמר בקול רם באופן שיהיה זה המאמר אליהם וכן אמר בפרשת כי תבוא וענו הלוים ואמרו אל כל איש ישראל קול רם ואמנם צוה שיהיה זה על ידי אחר כי הכהן המיוחד לזה ראוי שיהיה גדול המעלה כדרך שישמעו אליו כל ישראל ולפי שלא יהיה ראוי לאיש גדול להגביה קולו מאד חוייב שיהיה שם אחר לאמרם קול רם ולפי שביא אחר זה קצת הדברים ישנו אותם השוטרים להשמיעם אל העם למדנו שזה המאמר שיאמר או הדברים שזכר ראשונה הוא יותר נכבד מהשוטרים ולזה אמרו שהוא כהן אחר ולפי שצוה לדבר אליהם אלו הדברים למדנו שחייב לאמרם בזה הלשון שנאמרו בתורה:
@71 **שמע ישראל אתם קרבים היום למלחמה על אויביכם.** אמר זה להודיעם שצריך שישתדלו שינצחום על כל פנים שאם יפלו בידם לא יחמלו עליהם לפי שהם אויביהם:
@71 **אל ירך לבבכם.** אמר זה לפי שרכות הלבב והפחד הוא סבה ליראה והיראה הוא סבה אל שלא יתנהג האדם בחכמה ובדרכי הגבורה בענין המלחמה אבל יתנהג בחפזה ובבלי ההתישבות וזה יהיה סבה להשבר לבם רוצה לומר שיערצו ויחתו:
@72 **כי יי' אלהיכם וגו'.** כי יי' שהוא מנהיג אתכם ומשגיח הנה הוא הולך עמכם למלחמה רוצה לומר ששכינתו דבקה בכם להלחם בעבורכם עם איביכם או להושיע אתכם מידם כאמרו יי' ילחם לכם והראה בזה המאמר שאם יהיו ישראל ראויים שינצחו אויביהם מפני שקדם בדרכי התורה הנה השם יתעלה הולך עמם להלחם בעבורם אם אויביהם ואם אין ישראל באופן שתדבק בהם כמו ההשגחה הזאת או שלא שלם עון אויביהם עדיין הנה השם יתע' הולך עמם במחנה להושיע אותם מיד אויביהם:
@73 **ודברו השטרים אל העם לאמר.** ידוע שאלו הדברים ראויים היות קודם הדבור הראשון שזכרנו הוא מה שאמר אל תיראו וגו' כי הדבור ההוא איננו ראוי כי אם להולכים להלחם לא להולכים ושבים לביתם ולזה הוא מבואר שאלו הדברים יאמר הכהן תחלה בעת היות ישראל סמך ליציאת ארצם. והדבור שזכר תחלה יאמר סמוך ערכם המלחמה שנאמר כקרבכם אל המלחמה:
@73 **מי האיש אשר בנה בית חדש ולא חנכו.** לא דקדקה התורה שיבנהו אבל כיון שהוא חדש לו שלא חנכו ינהג בו זה הדין שזכר אך אם יש בחנכו עברה כגון שגזלו הוא מבואר שלא יחזור מפני זה ולזה גם כן אמר אשר בנה כי לפי הנהוג יבנה האדם משלו ולפי שאמר בית למדנו שהוא ראוי שיהיה באופן שידבק בו גדר הבית והנה סתם הבית הוא שיהיה ראוי לדירה:
@73 **ילך וישוב לביתו.** צוהו שילך וישוב לביתו שמא ימות במלחמה ואיש אחר יחנכנו והנה אמר זה כי אם ילך במלחמה ידאג על שלא זכה לחנך הבית ויחשוב שבעבור זה סבב השם יתעלה המלחמה לבעבור מנעו שלא יחנכו ויחנכנו אחר ויהיה זה סבה אל שירך לבבו ויירא במלחמה ויבא מפני זה רע לאנשי הצבא והנה ענין לכתו ושובו הוא לספק מים ומזון לבני החיל:
@74 **ומי האיש אשר נטע כרם ולא חללו.** הנה לא דקדקה התורה שיהיה הוא הנוטע איך שיהיה שלא חללו עדין רוצה לומר שלא זכה לאכול ממנו כי עד השנה הרביעית לא יזכה לזה כי השלשה שנים הראשונים יהיה כל פריו ערלה ולפי שלא דקדקה התורה כי אם מפני היראה שיש לו שאיש אחר יחללנו למדנו שכן הדין בכל אילני מאכל שיהיה בהם הרבוי כמו הענין בכרם והנה מצאנו באילנות שם כרם אמר מגדיש ועד קמה ועם כרם זית והנה הפחות שיפול עליו זה השם מהאילנות הם חמשה ולזה יתבאר שאם היו לו חמשה אילני מאכל ולא זכה עדיין לחללם ולאכול מהם הוא הולך ושב לביתו לסבה שזכרנו בענין הבית:
@75 **ומי האיש אשר ארש אשה ולא לקחה.** הנה למדנו מאמרו ואיש אחר יקחנה שאין הקפדה בזה אלא מפני זה הפחד שיהיה לו לסבה אשר זכרנו בענין הבית ולזה הוא מבואר שזה הדין נוהג בכל אשה שתהיה קנויה לו קצת:
@75 **ולא לקחה.** היתה בתולה או אלמנה או שומרת יבם ואם היה בלקוחיה עבירה אינו חוזר מפני זה וזה מבואר וכן המחזיר גרושתו שהרי לקחה וראוי שתדע שמי שארס אשה ולקחה אינו יוצא כלל לצבא עם עורכי המלחמ' ואינו הולך ושב לספק לאנשי הצבא מזונותיהם שנאמר נקי יהיה לביתו שנה אחת ושמח את אשתו אשר לקח כמו שיתבאר במה שיבא בג"ה בפרשת כי תצא ושם התבאר שכן הדין במי שבנה בית חדש וחנכו וכאשר נטע כרם וחללו:
@76 **ויספו השטרים לדבר אל העם וגו'.** ראוי שתדע שעד זה המקום היו דברי הכהנים ראשונה בצאתם מהארץ והשוטרים היו משמיעים זה לעם אחריו אולם בקרבם למלחמה יאמר הכהן כדברי' הראשונים תחלה והוא אמרו שמע ישראל וכהן אחר יאמר הדברים ההם לישראל בקול רם ואחר זה ישוב הכהן לאמר מי האיש אשר בנה וגו' והשוטר משמיע אחריו אלו הדברים לכל ישראל בקול רם והנה אלו השוטרים הם שוטרי של סנהדרי גדולה שהם משותפים לכל ישראל ולזה לא תהיה זאת המלחמה רוצה לומר מלחמת הרשות כי אם על פי בית דין הגדול שהשוטרים הם תחת השופטים ובמצותם יעשו כל מה שיעשו:
@76 **ויספו השטרים לדבר אל העם וגו'.** רוצה לומר שזה המאמר יוסיפו השוטרים לדבר אל העם יותר ממה שישמעו מפי הכהן:
@76 **מי האיש הירא ורך הלבב ילך וישוב לביתו.** רוצה לומר שהיה רך הלב שאין לו כח לשמוע לדברי הכהן שהזהירם מזה מפני טבעו ומנהגו יפרד מאנשי המלחמה וילך וישוב לביתו לספק מזונותיהם לבני הצבא כדי שלא ימס לבב אחיו כלבבו בראותם פחדו והיותו נחפז לנוס כי כך דרך אנשי המלחמה רוצה לומר שבראותם איש אחד מהם נס ינוסו כלם:
@77 **והיה ככלות השטרים לדבר אל העם ופקדו שרי צבאות בראש העם.** מגיד שכל אלו הדברים הם סמוך לעת רצותם לערוך המלחמה ולזה אמר כי תכף שישלימו אלו הדברים ימנו שרי צבאות בראש העם להנהיגם בסדור הראוי לדבר המלחמה ולפי שהשתדלותם היה שלא יגרום איש מהאנשים אשר שם שימס לבב העם היו ממנים אנשי' אחרים גבורי כח ישמרו שלא ינוסו איש מהם כדי שלא ימס לבב העם כלבבו וראוי שתדע שאלו הדיינים ממה שאמר פה מי האיש אש בנה בית גו' אינו נוהג אלא במלחמת הרשות אבל במלחמת מצוה כלם יוצאים והראיה כי במלחמת הרשות מדבר מה שאמר אחר זה כי תקרב אל עיר להלחם וגו' שהיא מלחמת הרשות כמו שהתבאר שם והראיה עוד שבמלחמת מצוה כלם יוצאים מה שאמר משה לבני גד ולבני ראובן כי נשיהם וטפם ישארו בעריהם והם יעברו חלוצים עם אחיהם מגיד שלא נשאו שם מהם כי אם נשיהם וטפם ואולם מה שאמר תחלה שיאמר הכהן שמע ישראל הוא נוהג גם במלחמת מצוה שהרי מצאנו בתורה שהזהיר השם יתעלה פעמים רבות שלא ייראו מאותם הגוים ואל יערצו מפניהם אך לא היו אומרים מי האיש הירא כי כלנו חייבים להחרים הגוים ההם:
@78 **כי תקרב אל עיר להלחם עליה וקראת אליה לשלום.** מגיד שקודם שילחמו עליה יחוייב שיקראו לה לשלום ואם יענו שהם רוצים להיות בשלום עם ישראל ויסכימו כל העיר לפתוח לישראל הנה כל העם הנמצא בה יהיו לישראל למס ויעבדו אותם וזה משותף למלחמת הרשות ולמלחמת המצות כמו שנתבאר בספר יהושע שנאמר לא היתה עיר אשר השלימה אל בני ישראל וגו' כי מאת יי' היתה לחזק את לבם לקראת המלחמ' למען החרימם וזה ראיה שאם היו משלימים לא היו חורגים אותם ולפי שאסור לישראל להניח עובד עבודה זרה בארצם שנאמר לא ישבו בארצך פן יחטיאו אותך לי למדנו שהוא מחוייב כשישלימו שיקבלו שלא לעבוד עבודה זרה ויקבלו עם זה כל המצות שנצטוו בני נח בהם כדי שיכנעו למצת שהם מחוייבים בהם והם שפיכות דמים ואבר מן החי ויתר המצות שהתבאר מהתורה שנתחייבו בהם כמו העריות והגזל כי עליהם היה המבול. ואמר אברהם ואמרו אשתו זאת והרגו אותי ואותך יחיו מגיד שכלם היו נשמרים מערכיות לפי דיניהם. ואולם ברכת יי' היא בכלל עבודה זרה ואין לך חטאה גדולה מזו וכן מחוייבים להושיב דיינין במקומותיהם ולהעמיד אלו הדינים שנאמר שופך דם האדם באדם דמו ישפך וזה אי אפשר מזולת שופט וכשיקבלו עליהם זה צריך שיקבלו עליהם עם זה להיות לישראל למס ולעבדם שנאמ' והיה כל העם הנמצא בה יהיו לך למס ועבדוך והנה ענין המס יכלול מס הגוף והממון כאמרו וזה דבר המס אשר העלה המלך שלמה לבנות את בית יי' ואת המלוא ואת חומת ירושלם ואת כל ערי המסכנות אשר היו לשלמה כל העם הנותר מן האמורי ויעלם שלמה למס עובד למדנו מזה שיש להכריחם לעשות עבודת המלך ולבנות חומה והבתים ומה שיצוו עליו או שיהיו חוטבי עצים ושואבי מים לבית יי' כמו שגזר יהושע לגבעונים ואולם מס הממון הוא שיתנו שנה בשנה סך מה והנה ימשך מענין העבודות שלא יהיו מושלים על ישראל וינהגו כמנהג העדים להיות שפלים לפני ישראל:
@80 **ואם לא תשלים עמך וגו'.** רוצה לומר אם לא תסכים להשלים עמך אך יצאו לעשות מלחמה לישראל או יעמדו תוך העיר ולא ירצו לפתוח לך ולא יצאו גם כן למלחמה אז תתן העיר במצור כדרך שלא יכנס בה שום מזון מחוץ וכאשר יתנה יי' בידיך באי זה שיהיה מאלו הדברים הנה תכה את כל זכורה לפי חרב רוצה לומר האנשים הגדולים כי הזכרים והטף והנשים והבהמה וכל אשר תהיה בעיר וכל שללה תבוז לך:
@82 **ואכלת את שלל אויבך אשר נתן יי' אלהיך לך.** מגיד שגם המאכלות האסורות שימצאו שם יוכלו לאכול כאלו תאמר החזירים המלוחים והנבלות והטרפות אך העבודה זרה והנטפל אליה אסורה כמו שקדם וזה אמנם התירה להם התורה אם ירעבו ולא ימצא להם מה לאכול זולת זה כדי שלא תרפנה ידיהם מן המלחמה:
@83 **כן תעשה לכל הערים הרחוקות.** מגיד שזה אינו נוהג רוצה לומר להחיות הנשים והטף אלא בערים הרחוקות שאינם משבעה עממין אך אם הם משבעה עממין ולא השלימו אסור להחיות מהם הנשים והטף ולזה הוזהרו שלא למות מהם כל נשמה במקום שהיו מחיים קצתם בערי שאר הגוים והטעם כדי שלא ילמדו ישראל לחטא באלו התועבות שגדלו עליהם:
@87 **כי תצור אל עיר ימים רבים.** רוצה לומר אחר שלא הסכימה העיר להשלים עמך וכונה לעשות עמך מלחמה אם לא תוכל להמלט בדרך אחרת כי קודם זה לא יצורו עליה כמו שקדם:
@87 **לא תשחית את עצה לנדוח עליו גרזן כי ממנו תאכל.** מגיד שאסור להשחית אילן מאכל אע"פ שהוא מהאויבים הנלחמים עם ישראל כ"ש אם היה משל ישראל והנה זה לא יהיה אלא כשהיה בזה השחתה אך אם אין בו השחתה רק תועלת יוכל האד' לקצצו ולזאת הסבה ג"כ אסור למנוע מאילן מאכל אמת המים שהוא שותה ממנו כדי שלא יבש וישחיתהו:
@87 **כי האדם עץ השדה לבא מפניך במצור.** רוצה לומר האם עץ השדה הוא אדם שיוכל להיות נכנס מפני אימתך תוך העיר בסבת המצור שאתה צר עליה והנה ה"א מלת האדם הוא ה"א התמה:
@88 **רק עץ אשר תדע כי אל עץ מאכל הוא.** רוצה לומר כמו שהיה אילן סרק או היה ממין עץ מאכל אך יבש כדרך שלא יעשה פירות אותו תשחית ותכרות לבנות מצור על העיר אשר לא שלימה עמך ומבקשת לעשות עמך מלחמה עד שתכבוש אותה ותנהג אז בה לפי הדינים הנזכרים ולפי שאמר עד רדתה למדנו שאפילו בשבת יוכל לבנות המצור ולעסוק במלחמה כיון שהתחילו זה קודם השבת כי אינם מפסיקים דבר המלחמה הזאת מפני שום סבה ולפי שאמר העושה עמך מלחמה למדנו שאם היו רוצים לברוח אין מוחין בידם אף על פי שלא השלימו ולזה בבנותם המצור לא יקיפו העיר מכל רוחותיה אך יניחו רוח אחד שאם יסכימו לברוח דרך שם יוכלו לברוח ואין אנחנו מצווים להמיתם אף על פי שלא הסכימו לקבל עליהם המצות שזכרנו כיון שלא ישבו בארצנו ומניחי' לנו העיר שלהם:
@89 **כי ימצא חלל באדמה אשר יי' אלהיך נותן לך לרשתה.** הנה זה כולל ארץ ישראל ועבר הירדן כי שתיהם נתנם השם יתעלה לרשת:
@89 **כי ימצא חלל.** רוצה לומר שימצא חלל בעת שימצא אבל אם היה מפרכס עדיין או שהיה נחנק אינו נקרא חלל:
@89 **באדמה.** ר"ל על הארץ לא שיהיה טמון בגל:
@89 **נופל בשדה.** לא שיהיה תלוי באילן כי אינו נופל ולא צף על פני המים כי אינו בשדה ולא בתוך העיר כי איננו בשדה:
@89 **לא נודע מי הכהו.** מפני שלא אמר אין עד מי הכהו למדנו שכיון שנודע זה לאחר זולתי המכה לא ינהג בו זה הדין ואפילו היה עבד או אשה שהרי אני קורא בו נודע מי הכהו כיון שנודע לזה:
@90 **ויצאו זקיניך ושופטים.** כיון שאמ' אחר זה זקני העיר ההיא למדנו שאלו הזקנים והשופטים הם הכוללים לכל. העירות ולזה יהיו מבית דין הגדול שבירושלם וראוי היה להיות כן כי אין ראוי שימדוד זה רק מי שהוא על העיירות כלם לשפוט מי מהם יתחייב להביא העגלה ולפי שהמעט שיפול בו שם זקניך הוא שנים והמעט שיפול בו שם שופטיך הוא שלשה כדי שיהיה ראוי לבית דין שלא יהיה בית דין שקול בלי מכריע למדנו שחמשה יוצאים מבית דין הגדול:
@90 **ומדדו את הערים אשר סביבות החלל.** ראוי שתדע שזאת המדידה יחוייב שתהיה מהמקום הנראה בו החיות יותר והוא הראש כי מהמקום ההוא ראוי שיקרא חלל ובחוטם ממנו לפי שבו יוכר תכף אם האדם מת מצד הנשימה והנה אם היו שם חללים רבים מפוזרין מודדין כל אחד בפני עצמו ואם היו זה על זה מודדין מן העליונים כי האחרים ממונים ולפי שכבר נאמר אחר זה ולקחו זקני העיר ההיא למדנו שעיר שאין בה בית דין לא היו מודדין לה ולמדנו מזה עוד שהעיר שהזקנים שבה אינם זקני העיר ההיא אבל זקניך כמו הענין במקום הבחירה לא היו מודדין לה:
@91 **והיה העיר הקרובה אל החלל.** ידמה ממה שאמר בזה כי העיר ההיא מביא העגלה מפני שחזקם שמשם הוא הרוצח והוא מבואר שעיר גדולה ועיר קטנה אף על פי שהעיר הקטנה היא יותר קרובה הנה העיר הגדולה היא יותר קרובה אל החלל כי יותר ראוי שימצאו שם רוצחים מהמצאם בעיר הקטנה והנה מצאנו בתורה שהלכה אחר הרוב שנאמר אחרי רבים להטות ומצאנו בזה המקום שהלכה אחר הקרוב. וזהו אמנם בעיירות שוות:
@91 **ולקחו זקני העיר ההיא.** זהו בית דין שבאותו מקום הקרוב אל החלל:
@91 **עגלת בקר אשר לא עובד בה אשר לא משכה בעול.** והנה העגלה הוא עד שתי שנים לפי מה שיורה עליו הגדר אמר עגלת בקר שיהיה הוייתה ממנה:
@91 **אשר לא עובד בה.** להגיד שהעבודה פוסלת בה כמו הענין בפרה ויקרא עובדה כל מה שנעשה בה לצורך הבעלים לא לצורך עצמה:
@91 **אשר לא משכה בעול.** הנה אם עלה עליה ועל אינה נפסלת ואולם אם משכה בעול שאף על פי שלא חרשה נפסלת ולפי שלא אמר בה תמימה למדנו שאין המומי' פוסלין בה:
@92 **והורידו זקני העיר ההיא את העגלה אל נחל וגו'.** רוצה לומר אל נחל שירוצו מימיו בכח חזק:
@92 **אשר לא יעבד בו ולא יזרע.** לפי שאין הכונה בזה שלא יהיה נזרע המקום ההוא מעולם ולא נעבד כי זה ממה שאי אפשר לדעת אמתתו הנה הוא מבואר שהכונה שלא יזריע בנחל ההוא אחר זה ולא יעבד לעולם וזאת העבודה שנאסרה שם היא בגופה של קרקע כמו הענין בזריעה:
@92 **וערפו שם את העגלה בנחל.** רוצה לומר שבתוך הנחל יערפוה בקופיץ ממול העורף והנה הטרפה היא כמתה ואינ' עגלה כי אם שתוף השם ולפי שמצאנו שאסרה התורה ההנאה גם בנחל שתערף בה למדנו שהעגלה אסורה בהנאה ולזה כונה התורה אשר לא עובד בה כדי שתהיה בכללות משולל ההנות ממנה ולזה היתה עריפתה בנחל איתן כי המים ההם חיים שלא נעשה בהם מלאכה עם שזה יורה שלא היצתה הנאה בארץ שתחת הנחל מזמן רב ולזה ידמה שלא יהיה ראוי עשות מלאכה אחרת עם העריפה והנה העריפה יחוייב שתהיה ביום כמו שהתבאר בשרשים הכוללים:
@93 **ונגשו הכהנים בני לוי כי בם בחר יי'.** זכר בזה המקום שלא יחשוב חושב שתהיה זאת המצוה דבר רק לפי שאין בה הזאה ולא כי אם מעט מהדברים הנוהגים בקדשים ולזה ספר שה הענין הוא דבר גדול ולזה לא ישלם כי אם על יד הכהנים בני לוי:
@93 **לשרתו ולברך בשם יי'.** הוא ברכת כהנים והנה אלו לא יהיו אלא מעומד כי כן דרך השרות ואמר גם כן לעמוד ולשרת. והברכה בשם יתעלה היא גם כן מעומד שהרי גם מה שיברכו הלוים את יי' הוא מעומד כמו שקדם:
@93 **ועל פיהם יהיה כל ריב וכל נגע.** אמר כל ריב כי הם ראויים שיהיו בסנהדרי גדולה שיתבאר המחלוקת בדינים ובנגעים על פיהם עם שראיית הנגעים אינה כי אם על פי כהן:
@94 **וכל זקני העיר ההיא הקרובים אל החלל.** מגיד שכל הזקנים ששם מתקבצים על זה לאמר ידנו לא שפכו ואמר קרובים אל החלל ולא אמר הקרובה אל החלל להגיד שאף על פי שאין העיר יותר קרובה. הנה יתכן שיהיו הם יותר קרובים מפני רוב האנשים הנמצאי' בעיר היא יותר ממה שימצא מזה בעיר הקרובה ממנה:
@94 **ורחצו את ידיהם על העגלה הערופה בנחל.** מגיד שכלם רוחצים ידיהם שם והם בתוך הנחל במקום העריפה:
@95 **וענו ואמרו ידינו לא שפכו את הדם.** ראוי שתדע שזה המאמר לא יאמרו אותו הכהנים כי לא יצטרך לומר להם זה אבל יאמרו זה זקני העיר ההיא אשר ראוי שיהיה הרוצח מעירם ומגיד שאם ראה זה אחד מהם אף על פי שלא ידע מה הכהו אינה נערפת שהרי איננו יכול לומר ועינינו לא ראו וידמה שיאמרו זה להתנצלות וזה כי החטא הוא עליהם אם לא הישירו העם לשמירת דרכי התורה בדרך שלא תהיה ביניהם רציחת נפש ואם לא השגיחו בזה לשמרו לפי מה שראוי אם בא עליהם וזה המאמ' ראוי לאמרו כן בלשון הקדש כמו שהגביל אותו התורה:
@96 **כפר לעמך ישראל.** הנה זה המאמר יאמרו אותו המכפרים לעם והם הכהנים וזה מבואר ולזה אמרה התורה שיהיו נגשי' הכהנים בני לוי ואומרים אותו בלשון הקדש כמו שהוגבל פה והוא שכבר יאמרו כפר לעמך ישראל אשר פדית יי' ולא תתן דם נקי בקרב ישראל. מגיד שהחטא הזה הוא חטא לישראל כלו כי כלם נענשים עליו כמו שקדם והרצון באמרו ולא תתן דם נקי ולא תתן חטאת דם נקי והנה השם יתע' מכפר להם החטא אחר זה שנאמר ונכפר להם הדם והו' מבואר שהחטא אשר להם בשביל שקרה זה המקרה הרע בגבולם הוא מתכפר להם בזה אמנם הרוצח לא יכופר בזה ולזה אמר ונכפר להם ולזאת הסבה אמר במה שקדם ולאר לא יכופר הדם אשר שופך בה כי אם בדם שפכו:
@97 **ואתה תבער הדם הנקי מקרבך.** מגיד שאם תרצה לעשות הישר בעיני יי' תשתדל לבער דם הנקי בהרבותך החקירות בזה כדי שיתברר לך מי הכהו או ירצה בזה שכאשר תעשה הישר בעיני יי' לא יקרה בקרבך כמו זה החטא כי הזקנים יוכיחו העם ויקבלו כלם מוסרם ללכת בדרכי התורה הנה זה ביאור מה שיצטרך אל ביאור בזאת הפרשה:

@1 **שופטים ושוטרים תתן לך בכל שעריך. עד כי אתה בא אל הארץ.**
@34 **כי אתה בא אל הארץ וגומ' עד יד ביד רגל ברגל.**
@69 **כי תצא למלחמה על אויביך וגומ'. עד סוף הפרשה:**

@1 **ואולם התועלות המגיעות ממנה הם כ"א:**
@1 **התועלת** הראשון הוא במצות והוא שימנה ב"ד הגדול שופטים ושטרים בכל עיר ועיר שבארץ ישראל ושפטים ושטרים לאחד אחד מהשבטים ושימנו אותם ראויים לשפוט משפט צדק והנה התועלת בזאת המצוה מבואר להישיר בתכלית מה שאפשר אל שישמרו כל ישראל דרכי התורה בכללם ולזה שם להם מוכיחים בכל שער ושער כי הם חייהם ובסבת שמירתם התורה יאריכו ימים על האדמה ולזאת הסבה יחד מצות מנוי השפטים והשטרים בכל שער ושער אל הארץ כאלו יאמר ששאר המקומות אינם מוכנים כל כך אל שיגיע בהם כונת התורה בכללה אם שבזה תועלת עוד בעניינים המדיניים שבדברי ריבות האנשים קצתם עם קצת לא יצטרכו ללכת חוץ מעירם לשפוט ביניהם ואולם בית דין הגדול נוהג בין בארץ בין בחוצה לארץ הלא תראה כי בית דינו של משה היה נוהג במדבר ובית דינו של יהושע והבאים אחריו היו נוהגים גם בשני השבטים וחצי שלקחו נחלתם מעבר הירדן מזרחה:
@1 **התועלת** השני הוא במצות והוא מה שהזהיר מלמנות דיינים בלתי ראויים לעשות משפט שנאמר לא תטה משפט ומה שהזהיר מהכיר פנים בעניין זה המנוי שנאמר לא תכיר פנים ומה שהזהיר על לקיחת שוחד על דבר זה המנוי אפילו לבחור הראוי שנא' ולא תקח שחד ומה שצוה לרדוף בו ענין הצדק והיושר כדי שיהיה המנוי יותר שלם שאפשר והנה התועלת באלו המצות כלם הוא שיהיה זה המנוי בשלם שבפנים להישיר ישראל ללכת בדרכי התורה ולהנהיגם בהנהגתם:
@1 **התועלת** השלישי הוא במצות והוא מה שהזהירנו מלנטוע שום עץ אצל מזבח ה' אלהיך שלא להתנהג במנהגי' הפחותים שהיו נוהגים עובדי ע"ז ואפילו שתהיה הכונה בו לעבודת ה' אלהיך והנה סמך זאת האזהרה לדבר אזהרת לקיחת שחד להעיר כי כמו שהשחד יטה האנשים מהדרך הנכונה אע"פ שלא יכונו לקחת אותו כי אם לעשות היושר כן נטיעת האשרה אצל מזבח ה' יביא לתכלית רע ואע"פ שיחשבו בו העבודה לש"י כי זה יביא ללכת בשאר חקות הגוי' ההם ולעשות פעולותיה' המגונות וידמה עוד שסמכו לזה להעיר שלא ימנו עם הבית דין הגדול קצת דיינים בלתי הגונים ולזה המשילו לנטיעת האשרה אצל המזבח כי אצל המזבח היה מקום ב"ד הגדול כמו שנתבאר בפר' זקן ממרא:
@1 **התועלת** הרביעי הוא במצות והוא מה שהזהירתנו מלהקים לנו מצבה ואפילו לעבודת הש' יתע' וזה כלו להרחיק ההדמות לפעולות הגוים ההם:
@1 **התועלת** החמישי הוא במצות והוא מה שהזהירתנו מלזבח לה' בהמה שיש בה מום אפילו שהוא מום עובר או שנעבדה בה עבודה זרה שנאמ' לא תזבח לה' אלהיך שור ושה אשר יהיה בו מום כל דבר רע והנה התועלת בזאת המצוה מבואר כי אם יקריבו אלה לה' יביא זה לחשוב החסרון לה' יתעלה כי אנחנו רואים כי גם לפתחנו לא נביא משום דבר בלתי נבחר בעצמותו כל שכן לשם יתעלה:
@1 **התועלת** הששי הוא במצות והוא מה שצונו לסקול עובדי עבודה זרה אחר הדרישה והחקירה וערות השלם והתועלת בזאת המצוה מבואר:
@1 **התועלת** השביעי הוא במצו' והוא מה שהזהיר מהמית המת על פי עד אחד והתועלת בזאת האזהרה מבואר כי אולי בזה יהיה נספה בלא משפט עם שלא יתבאר שיהיה שם דרישה וחקירה:
@1 **התועלת** השמיני הוא במצות והוא מה שהקיש עדות שנים לעדו' שלשה לעניין הדרישה והחקירה ושאר הענינים והנה בזה התועלת למצוא שקר כשהעידו עליו רבים:
@1 **התועלת** התשיעי הוא במצות והוא מה שצונו לשפוט זקן ממרא על פי ב"ד הגדול בדין שהתבאר בו ורצה שיתפרסם זה לכל ישראל כדי שישמרו כלם התורה לפי מה שיורו בה בית דין הגדול שבבית הבחירה והתועלת בזאת המצוה מבואר כי היא חכמה לשמור גדרי התורה למען לא יבאו שועלים יפרצום:
@1 **התועלת** העשירי הוא במצות והוא מה שצונו לעשות בדברי התורה על פי התורה אשר יגידו בית דין הגדול שבבית הבחירה שנאמ' ועשית על פי הדבר אשר יגידו לך והתועלת בזאת המצוה מבואר ממה שקדם:
@1 **התועלת** האחת עשרה הוא במצות והוא במה שהזהירה מלסור מן הדרך אשר יגידו בית דין הגדול ימין ושמאל היה שיהיה מביאורי התורה או גזרות ותקנות שנאמ' לא תסור מן הדבר:
@1 **התועלת** השתים עשרה הוא במצות והוא מה שצונו למנות עלינו מלך אשר יבחר ה' באותם התנאי' שזכר והתועלת בזה הוא שיוציא' ויביאם ונלחם מלחמותם לעשות התורה ועובדיה:
@1 **התועלת** השלש עשרה הוא מה שהזהירה ממנות המלך מקהל גרים שמא יסור לסורו עם שלא ייראו ממנו העם מאד להיותו בלתי נכבד מאד בעיניהם ומזה המקום למדנו שאין ראוי למנות מלך פחות הצורה או בעל מום או בעל חסרונות אחרות שיבזוהו העם בעבורם ויביא זה שלא תהיה יראתו על פניהם:
@1 **התועלת** הארבע עשרה הוא במצות והוא מה שהזהיר המלך מלהרבות לו סוסים יותר מהמצטרך לו למרכבתו ולמרכבת פרשיו ועבדיו כדי שלא ישיב העם מצריימה בעבור הרבות סוס עם שזה יביאו אל הגאוה וישחית המזונות ללא צורך:
@1 **התועלת** החמש עשרה הוא במצות והוא מה שהזהיר המלך מלהרבות לו נשים כדי שלא יסור לבו מהשקידה בתורה וההמשך אליה:
@1 **התועלת** השש עשרה הוא במצות והוא מה שהזהיר המלך מלהרבות לו מאד כסף וזהב על הצריך לו לפי הוצאותיו כי זה יהיה סבה אל שירום לבבו ולסור מדרכי התורה ומהשקידה עליה בעבור רוב תשוקתו לאסיפת קניינים:
@1 **התועלת** השבע עשרה הוא במצות והוא מה שצוה המלך לכתוב ספר התורה לעצמו יתר על כל אדם והוא יהיה עמו תמיד ויקרא בו כל ימי חייו להמשיכו ליראת השם יתע' ואל הנמשך למצות התורה:
@1 **התועלת** השמנה עשרה הוא במצות והוא במה שהזהירתנו מלתת לשבט לוי חלק בבזה ולא בנחלת הארץ והנה התועלת באלו האזהרות הוא כדי שיהיו פנויים לעבודת השם יתעלה ולזה לא יברחו לצאת למלחמה ולא יהיה להם עסק בעבודת האדמה בדרך שיתבלבל בעבורו עיונם בדברי התורה:
@1 **התועלת** התשע עשרה הוא במצות מה שצונו לתת מבהמות חולין לכהן הזרוע והלחיים והקבה כשנשחט אותה והנה אמרו על דרך דרש כי זה היה להם בזכות פנחס הזרוע מפני שבו לקח הרומח שהכה זמרי וכזבי. והקבה כי מפני שהכה האשה אל קבתה. והלחיים שבם הלשון כי בו התפלל בעבור ישראל שנאמר ויעמוד פנחס ויפלל. ולפי הפשט נראה לי שסמכו אל מה שאמר ה' הוא נחלתו להעיר שזה השבט הוא זרוע ישראל וכחם וכל שכן הכהנים מהם כי הוא מישיר את ישראל בלשונו אל דרכי התורה כאמרו יורו משפטיך ליעקב ותורתך לישראל והוא המכין מזון לישראל רוצה לומר שבזכותן יוכן מהם המזון מאת השם יתעלה כמו הלחיים והקבה יכינו המזון אל הכבד והלב וזה כי הלחי התחתון הוא המתנועע בעת האכילה ושם יתעכל המזון קצת עול כמו שנתבאר במקומותיו בקבה יתעכל ויוכל וזה ממה שאינו צריך אל ביאור ולזה אחשוב שנתנו לו אלו שלשה דברים:
@1 **התועלת** העשרים הוא במצות והוא מה שצונו לתת ראשית הגז לכהן והתועלת בזאת המצוה להעיר שכל הטובות באות מאתו ית' עם שבאלו המתנות ישלם לכהן השלמות בתורה ובעיון וימשך מהם שלמות לישראל לפי מה שאפשר
@1 **התועלת** האחת ועשרים הוא במצות והוא מה שלמדנו שצריך שיהיו הכהנים עובדים משמרות משמרות ואולם ברגלים יהיה רשות לכהנים הראוים לעבודה לעשות קרבנות הרגל רוצה לומר הבאים מחמת הרגל ויחלקום ביניהם חלק בחלק ומזה המקום יתבאר אל שצריך שיהיו הלוים עובדים משמרות כדי שיושמו כלם איש על עבודתו ועל משאו כמו שהתבאר בפרשת נשא והוא מבואר שבזולת זה האופן לא ישלמו אלו העבודות באופן ראוי בבית הבחירה:
@34 **ואולם התועלות המגיעות ממנה הם ששה עשר:**
@34 **התועלת** הראשון הוא במצות והוא מה שהזהירנו מללמד לעשות כתועבות הגוים ההם ומההליכה בחקותיהם כי אם נקח קצת מנהגיהם יהיה זה סבה אל שנקחם כלם וימשך מזה עבודת אלהים אחרים:
@34 **התועלת** השני הוא במצו' והוא מה שהזהירנו מהעביר מזרענו באש למולך והנה התועלת בזאת האזהרה מבואר:
@34 **התועלת** השלישי הוא במצות והוא מה שהזהירנו מלקסום קסמים ולא לעונן ולנחש ולא שואל אוב וידעוני ודורש אל המתים והנה התועלת באלו האזהרות מבואר כי העניין יביא להאמין בדברי הבל ולהסיר ממנו הפתח היותר גדול שיהיה לנו לבאר שיש שם אלוה פועל כל הנמצאות ומשיג כל מה שבהם כי אנחנו נעמוד על זה בקלות ממה שנמצא משפע אלו ההודעות מהשם יתעלה לאדם בנבואה או בחלום כמו שביארנו בשני מספר מלחמות יי' ולזה אמר ישעיהו מי פעל ועשה קורא הדורות מראש כמו שביארנו שם וכשנאמין שמפאת הנחש או המתים שאין בהם רוח ואלו הפעולות המגונות תתחדשנה אלו ההודעות יסור ממנו זה התועלת הנפלא אשר אין פתח מבלעדיו לקנות שום שלמות אנושי ועוד שכבר ימשך מזה מההפסד להסיר מהאנשים התועלות המגיעות להם מההשגחה הפרטית או מההשגחה הכוללת כי יאמינו אלו הדברים ויסורו מפני זה מעשות מה שאם יעשוהו יגיעו להם תועלות עצומות או יתקרבו לעשות מה שהיה נמשך להם מאלו ההשגחות שלא לעשות וכדי לשמרם מהזק נפלא:
@34 **התועלת** הרביעי הוא במצות והוא מה שהזהירנו שלא יהיה בנו מכשף וחובר חבר והנה תועלת זאת המצוה מבואר כי מזה ימשך הפסד בדברים המדיניים עם שזה יביא לבטל ממנו הפתח היותר גדול שנעמוד ממנו על שיש בכאן אלוה פועל כל הנמצאות מפני מה שיחייב שיהיה כח באלו ההבלי' להמציא פעולות נפלאות יגיעו מהם במה שידמה למתחדש מהקרי וזה כי הפעולות ההם אין בעצמותם דבר שיתישר על התכלית שיגיע מהם וזה ממה שיביא לחשוב שכל הדברים מתחדשי' מהקרי ושבו די ספוק להמציא כל הנמצאות כמו שהיה רואה אפיקורוס וסיעתו:
@34 **התועלת** החמישי הוא מה שהודיע שהשם יתע' השגיח בישראל בלכתם בדרכיו שיגיעם ההודעות השלמות בדברים העתידים באמצעות הנביאים כדי שישמרו מהרע שלא יגיעם וישתדלו בטוב שיגיע באופן היותם שלם וזהו אמרו ואתה לא כן נתן לך ה' אלהיך נביא בקרבך מאחיך כמוני יקים לך ה' אלהיך וכבר השגיחה התורה עוד בזה שיגיעו לישראל העתידות על יד כהן גדול בשאלם לו למשפט האורי' כמו שביארנו במה שקדם ולולי שגרמו העונות לא נפקדו ממנו אחד משני אלו הדרכים לעמוד בהם על אמתת מה שעתיד להתחדש:
@34 **התועלת** השישי הוא במצות והוא מה שצונו לשמוע לדברי הנביא ולעשות מצותיו אפילו כנגד מצות התורה אם יצוה בהם לפי שעה זולת עבודה זרה והדומה לה שנאמר אליו תשמעון והנה התועלת בזאת המצוה מבואר כי בזה תמשך ההשגחה הפרטית לישראל תמיד והנה התועלת בה עוד במה שיצוה לעבור בקצת העתים על קצת המצות כי התורה למה שתעיין באופן כולל בהנהגה השלמה המישרת האומה אל הטוב הנה אפשר שיקרה בעאת מהעתים שיהיה יותר טוב לסור מקצת מצותיה ולפי שרצה השם יתעלה שיגיע הטוב בכללות בכל הזמן לעמו אשר לקח לו לנחלה הישיר לישראל אל מה שצריך שישתנה לפי שעה בעת ועת על יד נביאיו כי אי אפשר שיושם בתורה זה והנה זה הענין דומה לענין המופתים שיחדש השם יתעלה על יד הנביאים וזה כי הטבע הוא המסודר מהש' יתעלה בשלם שבפנים להגיע אל הטוב בדבר דבר מהדברים הטבעיים באופן כולל ולפי שבעת מהעתים יהיה יותר טוב שיסור קצת הסדור ההוא השגיח השם ית' שיעשה זה על יד נביאו בעת הצורך והנה הודיעה התורה שהעובר על דברי הנביא חייב מיתה בידי שמים כדי שיירא כל העם מעבור על מצותיו:
@34 **התועלת** השביעי הוא במצות והוא מה שצונו להמית נביא שקר והמתנבא בשם ע"ז ומה שצונו שלא נירא מהמית נביא שקר שנאמר אך הנביא אשר יזיד לדבר דבר בשמי אשר לא צויתיו ואשר ידבר בשם אלהים אחרי' וגו' לא תגור ממנו וכבר ביארנו התועלת מזה אצל באורנו לדברי זאת הפרשה:
@34 **התועלת** השמיני הוא במצות והוא מה שצוה להבדיל שלש ערים למקלט במקומו היותר נאותים מהארץ אל שישלם בהם המקלט מכל המקומות אחר הכנסם לארץ ונשלם להם הירושה והישיבה איש על מקומו לפי הגורל והתועלת בזאת המצוה הוא לנוס שם כל רוצח עד שיתבאר דינו כדי שלא יהרג על לא חמס בכפיו ולעמוד שם כל הורג נפש בשגגה עד מות הכהן הגדול להמלט נפשו מגואלי הדם ולענוש אותו על זאת השגגה שבאה על ידו ונמשך זה העונש כי אם לשגגה שאינה קרובה לאונס כמו שבארנו לפי שבדלת שלשה ערים האלה היתה לזה התכלית חייב שיבדילו אותם במקומות היותר נאותים לזה התכלית ולזה צוה לשלש גבול הארץ ולקחת גבול באמצע כל שליש מהם עיר למקלט ולזה צוה גם כן להכין הדרך תמיד אליהם בכל הצדדין אשר תשלם זאת ההבנה כמו שביארנו אצל באורינו דברי זאת הפרשה:
@34 **התועלת** התשיעי הוא במצות והוא מה שצונו להבדיל עוד ג' ערים למקלט אחר שיתן לנו השם ית' את כל הארץ אשר נשבע לאבותינו ולפי שלא ראינו במה שעבר שהיו שם נביאים הבדלת אלו הערים ידענו שהדבר הזה עתיד והרצון בו אחר כבישת ארץ השלש אומות הנשארות שנתן השם יתעלה לאברהם בברית בין הבתרים והם קני וקניזי וקדמוני וזה אמנם יהיה בימי מלך המשיח אשר אנחנו מקוים בואו:
@34 **התועלת** העשירי הוא בפנות התור' והוא מה שהודיענו כי בזכו' שמירת כל המצוה שהוא מצוה אותנו היום שתכליתה הוא לאהוב השם יתע' וללכת בדרכיו כל הימים ישלים השם יתעלה לנו נתינת כל הארץ אשר נתן לאבות ולזה באר כאן שהתורה הזאת תתקיים כל הימים לא תומר בעת מהעתים אם לא באופן שזכרנו ושאם היינו שומרי אותה בכללות כבר היה השם יתעלה מגיע לנו זה הטוב:
@34 **התועלת** האחד עשרה הוא במצו' והוא מה שצונו שלא לרחם על הרוצח להצילו מהמות והוא אמרו לא תחוס עינך והתועלת בזה מבואר כדי שיוסרו בזה האנשים משפיכות דמים:
@34 **התועלת** השנים עשר הוא במצות והוא מה שהזהיר מהשיג גבול בארץ ישראל בגלוי או בסתר שנאמר לא תשיג גבול רעך בנחלתך אשר תנחל והנה התועלת בזאת האזהרה מבואר בענינים המדיניים והיתה בזה בארץ ישראל אזהרה נוספת להודיע מעלת ארץ ישראל על שאר הארצות לזה היה החטא בה בזה הענין יותר עצום:
@34 **התועלת** השלש עשרה הוא במצות והוא לצוות שלא לחתוך הדין לכל עון ולכל חטאת על פי עד אחד כי אם על פי שני' עדים או שלשה עדים וכבר ביארנו התועלת המגיע מזאת המצוה בביאורינו לזה המאמר:
@34 **התועלת** הארבע עשרה הוא במצות והוא מה שצונו לדון בעדים זוממין על האופן שהתבאר בזאת הפרשה וכבר ביארנו התועלת המגיע מזאת המצוה בביאורינו לזאת הפרשה:
@34 **התועלת** החמש עשרה הוא במצות והוא מה שהזהיר מעשות כדבר הרע הזה שנאמר ולא יוספיו לעשות כדבר הרע הזה והוא לפי מה שאחשוב אזהרה למזימים את העדים שלא יזימום בדברי שקר ויחשבו שאין זה חטא להם כי אינם מעידים בעצת עדותם שעשו אלו העדי שום רע. אבל העידו שהם היו אז דרך משל ברומי וזה אינו חטא לעדים מצד עצמותו ולפי שלא ימשך מדבריהם הרע לעדים כי אם במקרה אולי לא יחושו אם יאמרו בזה דברי שקר כמו שלא יחוש אדם לומר שראובן אכל היום פולים ואף על פי שלא אכלם אחר שזה המאמר אינו מעלה לראובן ולא מוריד ולזה הוצרכה התורה להזהיר זאת האזהרה ולזה אמרה כדבר הרע הזה ולא אמרה הדבר הר הזכה ואולם לעדים זוממין. לא הוצרכה בכאן אזהרה שהרי אמרה תורה לא תענה ברעך עד שקר:
@34 **התועלת** השש עשרה הוא במצות והוא מה שהוזהרנו מלרחם על עדים זוממין מהביא עליהם הדין הראוי להם ומה שהזהירנו מלרחם על כל חובל בחבירו מהביא עליו הדין הראוי שנאמר לא תחוס עינך נפש בנפש עין בעין והנה התועלת באלו האזהרות מבואר:
@69 **ואולם התועלות המגיעות ממנה הם ז':**
@69 **התועלת** הראשון הוא במצות והוא מה שהזהיר מלירא מן האויבי' עובדי עבודה זרה כשנבא להלחם עמהם כי ראוי לנו לבטוח בהשם יתעלה שיעזרנו על זה מצד אהבתו אותנו וברשעתם והוא מבואר שלא יהיה זה כי אם בעובדי עבודה זרה לפי שהמקבלים עליהם מצות בני נח ישלימו עמנו כמו שנתבאר עם שאין ראוי שיקראו אויבים לנו כי אם אויבי השם יתעלה:
@69 **התועלת** השני הוא במצוות והוא מה שצוה לומר מהדברים לאנשי חיל על יד כהן והשוטרים ולפקוד שרי צבאות עם העם כדי שיהיה סדור הצבא באופן ראוי ישלם לו הנצוח:
@69 **התועלת** השלישי הוא במצוות והוא מה שצוה לקרא לשלום תחלה לכל עיר שנבא להלחם עמה ואפילו משבעה עממין כדי שאם ישובו לדרכם הרעה אשר בעבורו נתחייבו כלייה לא נמיתם כי השם יתעלה אינו חפץ במות הרשע ולא צוה השם יתעלה להחרים אותם אלא כדי שלא נלמוד מתועבותיהם והנה רצה התורה עם כל זה שיהיו לנו למס ועבדונו מפני היות לנו תורה יותר שלמה לאין שיעור וראוי שיהיו הבלתי שלמים השלמות האנושי עובדים השלמים כי בזה יתקרבו ללמוד מדרכיהם הלא תראה כי ישראל נותנים מתנות רבות לכהנים ללויים בעבור היותם מוכנים יותר אל השלמות:
@69 **התועלת** הרביעי הוא במצות והוא מה שצותה התורה שאם לא השלימו מצור על העיר עד רדתה בדרך שאם ירצו לברוח והמלט על נפשם יכלו לברוח ואם היה משבעה הגוים יחרימו הכל לא יחיו כל נשמה שאם יחיו מהם ילמדום לעשות כתועבותיהם ויקחו שללם ואם היו משאר אומות יהיו להם הנשים והטף ויקחו את כל אשר להם:
@69 **התועלת** החמישי הוא במצות והוא מה שהזהירנו מהשחי' כל עץ מאכל באי זה צד שיהיה כאלו ביאר בזה שאלו שצוו ישראל להחרימם לא היה ראוי שיהיה בהם שום תועלת במה שעתיד כי אם היה אפשר זה לא היה מצוה השם יתע' להחרימם כי גם בצמחים השגיח שלא נשחית העושה מהם פרי:
@69 **התועלת** הששי הוא במצות והוא מה שצונו לעשות מדבר עגלה ערופה כי ימצא חלל באדמה והנה היתה הכונה שתהיה משוללת מהתועלת וההנאה מעת הולדה וגם המקום שתערף שם לתועלת בעינו שצוה בכמו זה הענין בפרה אדומה כמו שביארנו שם:
@69 **התועלת** השביעי הוא ללמדנו שהמעשים המגונים שיעשו במקום מה הנה יש בזה חטא למי שראוי שישתדל בהנהגת בני המקום ולזה הוצרכו כל הזקנים לומר ידינו לא שפכו את הדם הזה ועינינו לא ראו ואמר גם כן שאם יעשו הישר בעיני יי' לדקדק בהנהגת העם יהיה זה סבה שלא יעשו כמו אלו הפעולות המגונות ולזה אמר ואתה תבער הדם הנקי מקרבך כי תעשה הישר בעיני יי':
